local config = {
  ui_story_5009_50090101_1_dialog_content = "This is the first letter I am sending from Eraveil.",
  ui_story_5009_50090101_2_dialog_content = "I want to thank the Lins... yes, the Lin Guild, for giving my deceased kin a proper burial.",
  ui_story_5009_50090101_3_dialog_content = "Oh, this is also my first time receiving a letter in Eraveil.",
  ui_story_5009_50090101_4_dialog_content = "This place has been isolated from the world for, what, 17 years?",
  ui_story_5009_50090101_5_dialog_content = "Look, it's the Eraveil Post. You can trace its history back a hundred years.",
  ui_story_5009_50090101_6_dialog_content = "I didn't realize it would be such a treacherous task to renovate it back then.",
  ui_story_5009_50090101_7_dialog_content = "<color=#e8d9bb>Flashback to the very start...</color>",
  ui_story_5009_50090101_8_dialog_content = "It's so blissful to be able to sleep in.",
  ui_story_5009_50090101_9_dialog_content = "\"(Beep) 2 days until Windelion.\"",
  ui_story_5009_50090101_10_dialog_content = "Don't remind me again. I know it's coming, I know.",
  ui_story_5009_50090101_11_dialog_content = "Forget it, I'm going back to sleep.",
  ui_story_5009_50090101_12_dialog_content = "\"(Beep) Vice is on the line.\"",
  ui_story_5009_50090101_13_dialog_content = "How have you been lately, PlayerName?",
  ui_story_5009_50090101_14_dialog_content = "You got more than 30 seconds for me this time?",
  ui_story_5009_50090101_15_dialog_content = "I'm sorry. I was swamped a few days ago and had no choice but to hang up on you...",
  ui_story_5009_50090101_16_dialog_content = "I'm okay with it, just a little concerned.",
  ui_story_5009_50090101_17_dialog_content = "Sorry, I've been busy trying to finish up the Dunefire Strike report.",
  ui_story_5009_50090101_18_dialog_content = "How are you doing in Eraveil?",
  ui_story_5009_50090101_19_dialog_content = "I'm doing okay. There's not much to do, anyway,",
  ui_story_5009_50090101_20_dialog_content = "other than reading and learning some everyday skills.",
  ui_story_5009_50090101_21_dialog_content = "Oh? What kind of skills?",
  ui_story_5009_50090101_22_dialog_content = "Sewing, handicrafts, drawing, stuff like that.",
  ui_story_5009_50090101_23_dialog_content = "I'm going to end up becoming a better cook than you if you don't come back soon.",
  ui_story_5009_50090101_24_dialog_content = "In your dreams! I've been studying culinary arts longer than you have.",
  ui_story_5009_50090101_25_dialog_content = "Studying? As in...",
  ui_story_5009_50090101_26_dialog_content = "Experimenting with new dishes, of course! You should try my...",
  ui_story_5009_50090101_27_dialog_content = "Ahem! That's all right. Let's talk about something else.",
  ui_story_5009_50090101_28_dialog_content = "Oh, I've been sensing more Eclipsites in Eraveil lately.",
  ui_story_5009_50090101_29_dialog_content = "Yeah. According to the latest report, some of the Eclipsites fleeing the Dunefire Line are heading toward Eraveil.",
  ui_story_5009_50090101_30_dialog_content = "Please be careful and don't run around by yourself!",
  ui_story_5009_50090101_31_dialog_content = "Relax! I'll stay put. I won't be charging into Eraveil for no reason, don't worry.",
  ui_story_5009_50090101_32_dialog_content = "That makes me feel much better.",
  ui_story_5009_50090101_33_dialog_content = "Okay, go back to your work.",
  ui_story_5009_50090101_34_dialog_content = "\"(Beep) 2 days until Windelion.\"",
  ui_story_5009_50090101_35_dialog_content = "Man, this reminder is getting on my nerves!",
  ui_story_5009_50090101_36_dialog_content = "Wait, did it just say Windelion?",
  ui_story_5009_50090101_37_dialog_content = "Yes, the Windelion Festival. You know about it?",
  ui_story_5009_50090101_38_dialog_content = "Of course I do, it's an Aurorian festival!",
  ui_story_5009_50090101_39_dialog_content = "Let me recall what the books say... Oh yeah!",
  ui_story_5009_50090101_A1_dialog_content = "Windelion originated with the Caelestites. It's a day for memorializing saints and lauding the Light...",
  ui_story_5009_50090101_40_dialog_content = "Hold on. How do Caelestites celebrate Windelion, PlayerName?",
  ui_story_5009_50090101_41_dialog_content = "We gather together to commemorate deceased loved ones and praise Mother Nature.",
  ui_story_5009_50090101_42_dialog_content = "Well, that's what Soroz told me, anyway. Soroz used to recite these traditions to me every year.",
  ui_story_5009_50090101_43_dialog_content = "Then I'd imagine what the gathering would've been like, what my loved ones would have looked like, what...",
  ui_story_5009_50090101_44_dialog_content = "Never mind, let's move on.",
  ui_story_5009_50090101_45_dialog_content = "Speaking of which, this will be your first Windelion on the surface.",
  ui_story_5009_50090101_46_dialog_content = "Hmm, yeah. Well, I gotta go now. Bye for now, Vice.",
  ui_story_5009_50090101_47_dialog_content = "Okay. See you later, PlayerName.",
  ui_story_5009_50090101_48_dialog_content = "\"(Beep) 2 days until...\"",
  ui_story_5009_50090101_49_dialog_content = "Okay, okay!",
  ui_story_5009_50090101_50_dialog_content = "\"First Windelion on the surface\"... That does sound special.",
  ui_story_5009_50090101_51_dialog_content = "Firefly! Firefly!",
  ui_story_5009_50090101_52_dialog_content = "\"At your command.\"",
  ui_story_5009_50090101_53_dialog_content = "Let's get the place in full Windelion mood!",
  ui_story_5009_50090101_54_dialog_content = "\"Order confirmed. Assistance mode engaged.\"",
  ui_story_5009_50090101_55_dialog_content = "\"(Beep) 2 days until Windelion. Let us decorate the rooms.\"",
  ui_story_5009_50090101_56_dialog_content = "\"Decorating rooms for the festival. Decorating rooms for the festival.\"",
  ui_story_5009_50090101_57_dialog_content = "\"Please enter the type of decorations desired.\"",
  ui_story_5009_50090101_58_dialog_content = "Hmm, I need to think about this... What's Windelion like, exactly?",
  ui_story_5009_50090101_59_dialog_content = "Ow, just thinking about this is giving me a headache.",
  ui_story_5009_50090101_60_dialog_content = "Come out, Soroz!",
  ui_story_5009_50090101_61_dialog_content = "Tell me what to put up for Windelion!",
  ui_story_5009_50090201_1_dialog_content = "May I have a word with you, your Highness?",
  ui_story_5009_50090201_2_dialog_content = "I know you. You're from the church, right?",
  ui_story_5009_50090201_3_dialog_content = "I'm actually a judge from Lumopolis, Your Highness. Wayne Pittman is my name.",
  ui_story_5009_50090201_4_dialog_content = "Oh, no wonder you looked familiar.",
  ui_story_5009_50090201_5_dialog_content = "I'm investigating Eclipsite transformation, hence I would like to ask you...",
  ui_story_5009_50090201_6_dialog_content = "Feel free to ask me anything you would like to know.",
  ui_story_5009_50090201_7_dialog_content = "Thank you. I believe you ran into Beryl Gautier recently, correct?",
  ui_story_5009_50090201_8_dialog_content = "Yes.",
  ui_story_5009_50090201_9_dialog_content = "I read your report on the incident with Beryl and Caroline, and I would like to verify their whereabouts.",
  ui_story_5009_50090201_10_dialog_content = "Caroline Pyrrhus? We handled her already.",
  ui_story_5009_50090201_11_dialog_content = "It's complicated. I'll continue my investigations. Please inform me should you receive more news.",
  ui_story_5009_50090201_12_dialog_content = "Complicated? Caroline's defeated, isn't that enough?",
  ui_story_5009_50090201_13_dialog_content = "Well, I'm actually referring to the insurgence of the Houses of Pyrrhus and Gautier.",
  ui_story_5009_50090201_14_dialog_content = "Wasn't that dealt with many years ago?",
  ui_story_5009_50090201_15_dialog_content = "It's complicated. I'll need a lot more evidence to make a definitive conclusion.",
  ui_story_5009_50090201_16_dialog_content = "I see. I shall leave you to it then.",
  ui_story_5009_50090201_17_dialog_content = "If you are heading to Eraveil, please permit me to come along.",
  ui_story_5009_50090201_18_dialog_content = "What do you mean by that?",
  ui_story_5009_50090201_19_dialog_content = "I discovered subtle clues in the report on the Dunefire Strike.",
  ui_story_5009_50090201_A1_dialog_content = "I have reason to believe that the Eclipsites are up to something bigger this time.",
  ui_story_5009_50090201_20_dialog_content = "According to the report, some of the defeated Eclipsites are converging toward Eraveil. I suspect...",
  ui_story_5009_50090201_21_dialog_content = "Fine. You can come and we'll talk about it on the way.",
  ui_story_5009_50090201_22_dialog_content = "Windelion... Dolls.",
  ui_story_5009_50090201_23_dialog_content = "\"Windelion dolls, a decor specifically for Windelion. Pleasant and adorable in appearance.\"",
  ui_story_5009_50090201_24_dialog_content = "\"Caelestites would stuff the dolls with candies or seeds and break them open during the festival.\"",
  ui_story_5009_50090201_25_dialog_content = "\"It's a game of thanksgiving and seeking blessings, loved by all children.\"",
  ui_story_5009_50090201_26_dialog_content = "But this doll looks like...",
  ui_story_5009_50090201_27_dialog_content = "\"Identified, a frog.\"",
  ui_story_5009_50090201_28_dialog_content = "\"Identified, a spider.\"",
  ui_story_5009_50090201_29_dialog_content = "\"Identified, a bat.\"",
  ui_story_5009_50090201_30_dialog_content = "The Firefly can't even tell that this is supposed to be Soroz... Maybe I just did such an awful job of making it?",
  ui_story_5009_50090201_31_dialog_content = "PlayerName!",
  ui_story_5009_50090201_32_dialog_content = "I didn't expect to hear from you! I thought you'd be occupied today too.",
  ui_story_5009_50090201_33_dialog_content = "I'm almost at Eraveil!",
  ui_story_5009_50090201_34_dialog_content = "What? You're on your way here?!",
  ui_story_5009_50090201_35_dialog_content = "But weren't you swamped with work?",
  ui_story_5009_50090201_36_dialog_content = "I've got a surprise for you, see you soon!",
  ui_story_5009_50090201_37_dialog_content = "Awesome, Vice is coming!",
  ui_story_5009_50090201_38_dialog_content = "\"It is your obligation to show hospitality to guests during festivals.\"",
  ui_story_5009_50090201_39_dialog_content = "Yeah, I should set things up before she gets here.",
  ui_story_5009_50090201_40_dialog_content = "We're here, PlayerName...!",
  ui_story_5009_50090201_41_dialog_content = "Welcome back, Vice.",
  ui_story_5009_50090201_42_dialog_content = "Why are you dressed like a rooster?!",
  ui_story_5009_50090201_43_dialog_content = "So this is your preferred fashion style...",
  ui_story_5009_50090201_44_dialog_content = "No, let me explain, Carleen!",
  ui_story_5009_50090201_45_dialog_content = "I see PlayerName wikes wed suits!",
  ui_story_5009_50090201_46_dialog_content = "Tweety's here too? Hey, and who are these people?",
  ui_story_5009_50090201_47_dialog_content = "They're here to help clean up Eraveil.",
  ui_story_5009_50090201_48_dialog_content = "Clean up?",
  ui_story_5009_50090201_49_dialog_content = "Weren't you saying more Eclipsites got into Eraveil?",
  ui_story_5009_50090201_50_dialog_content = "So we need to clean up first, then you can go home.",
  ui_story_5009_50090201_51_dialog_content = "By the way, we have a very important person here with us. She's...",
  ui_story_5009_50090201_52_dialog_content = "How do you do, I'm Naroxel, representing the Courier Union.",
  ui_story_5009_50090201_53_dialog_content = "Thank Mother Nature for finally guiding me to you, representative of the Caelestites.",
  ui_story_5009_50090201_54_dialog_content = "Uh, representative of the Caelestites? I guess can live with that. How do you do, I'm PlayerName.",
  ui_story_5009_50090201_55_dialog_content = "Your headwear is... very nice.",
  ui_story_5009_50090201_56_dialog_content = "It resembles a burning flame and red leaves falling in autumn.",
  ui_story_5009_50090201_57_dialog_content = "Thanks! Pleased to meet you!",
  ui_story_5009_50090201_58_dialog_content = "Don't flatter him too much, Naroxel. I don't want him getting the wrong idea about himself.",
  ui_story_5009_50090201_59_dialog_content = "I'll take it down. It's just decor for the festival.",
  ui_story_5009_50090201_60_dialog_content = "Windelion.",
  ui_story_5009_50090201_61_dialog_content = "Yes, yes, tomorrow is Windelion!",
  ui_story_5009_50090201_62_dialog_content = "It's a Caelestite festival for us to commemorate our ancestors and nature.",
  ui_story_5009_50090201_63_dialog_content = "The Caelestites would spruce up their houses, dress up, and...",
  ui_story_5009_50090201_64_dialog_content = "Wow. Is this messy room and weird headwear part of the festival's traditions?",
  ui_story_5009_50090201_65_dialog_content = "No! I only followed Soroz's directions and... experimented a little. Though I probably screwed up somewhere.",
  ui_story_5009_50090201_66_dialog_content = "What about this pile of dirt?",
  ui_story_5009_50090201_67_dialog_content = "I wanted to get some dandelions from Eraveil to plant in pots.",
  ui_story_5009_50090201_68_dialog_content = "But there were no dandelions, so I only ended up with dirt... I'll try to make it look better.",
  ui_story_5009_50090201_69_dialog_content = "And what's this spider thing with frog eyes and bat wings in the corner?",
  ui_story_5009_50090201_70_dialog_content = "Nothing, don't worry about it!",
  ui_story_5009_50090201_71_dialog_content = "*Ahem* I came here on the behalf of the Courier Union to...",
  ui_story_5009_50090201_72_dialog_content = "To deliver a gift just for me?",
  ui_story_5009_50090201_73_dialog_content = "Is it out of appreciation for my courageous exploits against the Eclipsites throughout the land?",
  ui_story_5009_50090201_74_dialog_content = "Don't be delusional, PlayerName.",
  ui_story_5009_50090201_75_dialog_content = "You could say it's a gift, but we prefer calling it a mission.",
  ui_story_5009_50090201_76_dialog_content = "A mission? What sort of gift is this?",
  ui_story_5009_50090201_77_dialog_content = "For a hundred years, the Union has been providing services for Eraveil and the Caelestites.",
  ui_story_5009_50090201_78_dialog_content = "But mail to and from Eraveil ceased altogether since the incident 17 years ago.",
  ui_story_5009_50090201_79_dialog_content = "Because we're neither able to enter Eraveil nor locate recipients, most of the mail designated for the place has been on hold in our storehouse.",
  ui_story_5009_50090201_80_dialog_content = "I feel vewy bad seeing the mail gathewing lotsa dust.",
  ui_story_5009_50090201_81_dialog_content = "We've always hoped to be able to deliver them to the Caelestites one day.",
  ui_story_5009_50090201_82_dialog_content = "Since you are now their sole representative...",
  ui_story_5009_50090201_83_dialog_content = "I see. Did you bring the mail?",
  ui_story_5009_50090201_84_dialog_content = "They must be delivered to the post or go back into storage, Union rules.",
  ui_story_5009_50090201_85_dialog_content = "The post? What is that?",
  ui_story_5009_50090201_86_dialog_content = "A post is what we set up to process mail. It is established after local residents and the branch reach an agreement.",
  ui_story_5009_50090201_87_dialog_content = "The post in Eraveil has been out of service for years.",
  ui_story_5009_50090201_88_dialog_content = "Oh? Can't we just fix it?",
  ui_story_5009_50090201_89_dialog_content = "We need a wepair and activation permission fwom Caewestites, or we can't do that.",
  ui_story_5009_50090201_90_dialog_content = "Alright. Actually, it's not even just repairing the post.",
  ui_story_5009_50090201_91_dialog_content = "Every time I think about rebuilding Eraveil, I ask myself...",
  ui_story_5009_50090201_A2_dialog_content = "\"Would the Eclipsites allow me to do that? They would probably tear it back down, anyway...\"",
  ui_story_5009_50090201_92_dialog_content = "It might be difficult, but we'll do our best to help.",
  ui_story_5009_50090201_93_dialog_content = "We brought a lot of people along this time because we want to clear the Eclipsites out of here. Then you can start rebuilding.",
  ui_story_5009_50090201_94_dialog_content = "Thank you, all of you.",
  ui_story_5009_50090201_95_dialog_content = "Let me go over the plan. Currently, there are two parties of Eclipsites in Eraveil.",
  ui_story_5009_50090201_96_dialog_content = "First are the ones retreating from Dunefire, and then there are the ones that have been here for years...",
  ui_story_5009_50090201_97_dialog_content = "Allow me to interject. The specific situation should be—",
  ui_story_5009_50090201_98_dialog_content = "You've stepped out of line, Pittman.",
  ui_story_5009_50090201_99_dialog_content = "Forgive me for being rude, your Highness.",
  ui_story_5009_50090201_100_dialog_content = "I only wish to divulge the most updated information.",
  ui_story_5009_50090201_101_dialog_content = "Who's that, Carleen?",
  ui_story_5009_50090201_102_dialog_content = "A judge from Lumopolis who's looking into the truth behind the Dunefire Strike.",
  ui_story_5009_50090201_103_dialog_content = "Truth?",
  ui_story_5009_50090201_104_dialog_content = "How do you do, PlayerName. Your reputation precedes you. I'm Investigator Wayne Pittman, from Lumopolis.",
  ui_story_5009_50090201_105_dialog_content = "Let's get back to business.",
  ui_story_5009_50090201_106_dialog_content = "I'll get straight to the point then. Besides the ones fleeing from the Dunefire Line, Eclipsites from other areas are also converging upon Eraveil.",
  ui_story_5009_50090201_107_dialog_content = "Word is that the Eclipsites from Dunefire adapted in terms of abilities and tactics.",
  ui_story_5009_50090201_108_dialog_content = "I'm concerned they intend to launch a similarly major offensive on Eraveil, thus the reason I'm here.",
  ui_story_5009_50090201_109_dialog_content = "I understand. But regardless of what they're planning, victory will be Illumina's.",
  ui_story_5009_50090201_110_dialog_content = "Why Illumina?",
  ui_story_5009_50090201_111_dialog_content = "Why Illumina?",
  ui_story_5009_50090201_112_dialog_content = "Come on, we should go now.",
  ui_story_5009_50090201_113_dialog_content = "Let's eliminate all the Eclipsites before Windelion comes!",
  ui_story_5009_50090301_1_dialog_content = "Gah!",
  ui_story_5009_50090301_2_dialog_content = "I didn't expect to see this many Eclipsites already, and we've yet to enter.",
  ui_story_5009_50090301_3_dialog_content = "Yeah, but don't worry, there aren't any particularly powerful Eclipsites among them right now.",
  ui_story_5009_50090301_4_dialog_content = "Are we ready, everyone?",
  ui_story_5009_50090301_5_dialog_content = "Yeah!",
  ui_story_5009_50090301_6_dialog_content = "Then let's move in according to plan and begin clearing out the Eclipsites!",
  ui_story_5009_50090301_7_dialog_content = "Charge!",
  ui_story_5009_50090301_8_dialog_content = "There they go... They seem to be even more enthused than I am!",
  ui_story_5009_50090301_9_dialog_content = "The strength of our Illumina soldiers lies in their enthusiasm. Rest assured, they'll carry out the operation.",
  ui_story_5009_50090301_10_dialog_content = "We can go to the post right now.",
  ui_story_5009_50090301_11_dialog_content = "Speaking of which, which way do we go, PlayerName?",
  ui_story_5009_50090301_12_dialog_content = "Uh... I'm not sure either.",
  ui_story_5009_50090301_13_dialog_content = "Please allow me to check my mission guide. Ah, it says...",
  ui_story_5009_50090301_14_dialog_content = "The Courier Union post is located on the giant white tower in northeast Eraveil.",
  ui_story_5009_50090301_15_dialog_content = "How do you know that, Mr. Pittman?",
  ui_story_5009_50090301_16_dialog_content = "I've done investigations here before and have read a lot of files on Eraveil.",
  ui_story_5009_50090301_17_dialog_content = "Northeast should be this way...",
  ui_story_5009_50090301_18_dialog_content = "Is this...",
  ui_story_5009_50090301_19_dialog_content = "Yes, these are Caelestite burial grounds.",
  ui_story_5009_50090301_20_dialog_content = "Those who died 17 years ago were buried here too.",
  ui_story_5009_50090301_21_dialog_content = "PlayerName...",
  ui_story_5009_50090301_22_dialog_content = "I'm okay.",
  ui_story_5009_50090301_23_dialog_content = "These graves... they have markings of the Lins from Umbraton.",
  ui_story_5009_50090301_24_dialog_content = "Marking? The Lins?",
  ui_story_5009_50090301_25_dialog_content = "Yes, this earthly burial and the rocky tombstone are in the family's style.",
  ui_story_5009_50090301_26_dialog_content = "What? I don't get it.",
  ui_story_5009_50090301_27_dialog_content = "Simply put, the Lins buried your people and left the tombstones.",
  ui_story_5009_50090301_28_dialog_content = "They're one of the most famous guilds in the world. Vice and Carleen, you two must know of them.",
  ui_story_5009_50090301_29_dialog_content = "Yes, I also know the Lins were on good terms with the Caelestites and Northland.",
  ui_story_5009_50090301_30_dialog_content = "It seems Naroxel is correct in that the Lins buried the Eraveil dead in accordance with their customs.",
  ui_story_5009_50090301_31_dialog_content = "To Caelestites, resting in the earth represents a return to nature, which we will become part of after death.",
  ui_story_5009_50090301_32_dialog_content = "The Lin Guild...",
  ui_story_5009_50090301_33_dialog_content = "Let's first finish what we came here to do.",
  ui_story_5009_50090301_34_dialog_content = "Alright.",
  ui_story_5009_50090302_1_dialog_content = "The landmark white tower known as the Deepvalley Beacon...",
  ui_story_5009_50090302_2_dialog_content = "should not be too far ahead.",
  ui_story_5009_50090302_3_dialog_content = "We'll split up into two groups. I'll go handle the Eclipsites with Vice and the others. You head for the post.",
  ui_story_5009_50090302_4_dialog_content = "Okay! I wun fast, I go wook!",
  ui_story_5009_50090302_5_dialog_content = "And we'll handle the repair of the post.",
  ui_story_5009_50090302_6_dialog_content = "We promise you'll see a brand-new site when you come back.",
  ui_story_5009_50090302_7_dialog_content = "I'm sure. Thank you.",
  ui_story_5009_50090302_8_dialog_content = "Let's keep heading east and get the Eclipsites over there.",
  ui_story_5009_50090302_9_dialog_content = "Oh, your presence is also required for a ceremony.",
  ui_story_5009_50090302_10_dialog_content = "What ceremony?",
  ui_story_5009_50090302_11_dialog_content = "Worry not, it will only take a few minutes.",
  ui_story_5009_50090302_12_dialog_content = "First, we must verify your identity. Though of course, that has already been done.",
  ui_story_5009_50090302_13_dialog_content = "Then we need you to sign two documents.",
  ui_story_5009_50090302_14_dialog_content = "The first is the Post Agreement. Please sign it, then sign the Permission to Work.",
  ui_story_5009_50090302_15_dialog_content = "Sounds complicated... Let me take a closer look.",
  ui_story_5009_50090302_16_dialog_content = "Is it really necessary to this right before battle?",
  ui_story_5009_50090302_17_dialog_content = "<color=#e8d9bb>A few minutes later...</color>",
  ui_story_5009_50090302_18_dialog_content = "My eyes are glazing over... I'll just sign it now.",
  ui_story_5009_50090302_19_dialog_content = "Lastly, we have a Document of Verification...",
  ui_story_5009_50090302_20_dialog_content = "I have to sign this too? Whoa, another long one!",
  ui_story_5009_50090302_21_dialog_content = "Just sign it! The Union is trustworthy, they won't scam you.",
  ui_story_5009_50090302_22_dialog_content = "However, for weird documents from anyone else, make sure you read them through first!",
  ui_story_5009_50090302_23_dialog_content = "This one can wait until the post is rebuilt.",
  ui_story_5009_50090302_24_dialog_content = "Also, after we reach the White Tower post...",
  ui_story_5009_50090302_25_dialog_content = "We'll send coordinates to the Union and provide a damage report.",
  ui_story_5009_50090302_26_dialog_content = "The Union will send assistance accordingly, so we can guarantee completion today.",
  ui_story_5009_50090302_27_dialog_content = "Please look forward to the new facility.",
  ui_story_5009_50090302_28_dialog_content = "Nawoxel, I founds the White Tower over there!",
  ui_story_5009_50090302_29_dialog_content = "We'll get going, then.",
  ui_story_5009_50090302_30_dialog_content = "Good wuck fighting, PlayerName!",
  ui_story_5009_50090302_31_dialog_content = "I'll do my best!",
  ui_story_5009_50090302_32_dialog_content = "We'll get rid of every Eclipsite in Eraveil!",
  ui_story_5009_50090401_1_dialog_content = "Target spotted northeast, my lord!",
  ui_story_5009_50090401_2_dialog_content = "My, my. The lovely princess enters the valley for a rendezvous with her charming knight...",
  ui_story_5009_50090401_3_dialog_content = "What kind of lame story is this? I hate it!",
  ui_story_5009_50090401_4_dialog_content = "Well, our opportunity has come!",
  ui_story_5009_50090401_5_dialog_content = "But there are a lot of Aurorians in Eraveil right now...",
  ui_story_5009_50090401_6_dialog_content = "Making a move... might be risky.",
  ui_story_5009_50090401_7_dialog_content = "You don't think I can beat them?",
  ui_story_5009_50090401_8_dialog_content = "I'm going to devour you for ruining my mood!",
  ui_story_5009_50090401_9_dialog_content = "M-My lord...?",
  ui_story_5009_50090401_10_dialog_content = "Hahaha! Are you shuddering?",
  ui_story_5009_50090401_11_dialog_content = "I'll spare you this time only because you can speak Universese.",
  ui_story_5009_50090401_12_dialog_content = "But, but... the Caelestite is present too.",
  ui_story_5009_50090401_13_dialog_content = "I heard he can sense us using psychic abilities.",
  ui_story_5009_50090401_14_dialog_content = "So what?",
  ui_story_5009_50090401_15_dialog_content = "You know, I might as well get that Caelestite, too, for supper.",
  ui_story_5009_50090401_16_dialog_content = "I'm such a genius!",
  ui_story_5009_50090401_17_dialog_content = "Go notify the other lowly Eclipsites and tell them to get ready!",
  ui_story_5009_50090401_18_dialog_content = "How is your psychic ability, PlayerName?",
  ui_story_5009_50090401_19_dialog_content = "I wouldn't say it's very powerful, but it's more than adequate.",
  ui_story_5009_50090401_20_dialog_content = "I can sense the location of Eclipsites from a distance and tell which ones are special.",
  ui_story_5009_50090401_21_dialog_content = "Would you mind describing what was different about the special Eclipsites you encountered on the Dunefire Line?",
  ui_story_5009_50090401_22_dialog_content = "Most of them were of the average type, just more ferocious.",
  ui_story_5009_50090401_23_dialog_content = "But the elites we met in Undercity 13 were very smart. They were fighters.",
  ui_story_5009_50090401_24_dialog_content = "Also, they were capable of probing for openings and using sandstorms for cover.",
  ui_story_5009_50090401_25_dialog_content = "Yes, I noticed the sandstorms too.",
  ui_story_5009_50090401_26_dialog_content = "According to my findings, the sandstorms and energy fluxes at Dunefire may not have been natural phenomena.",
  ui_story_5009_50090401_27_dialog_content = "At least, not entirely natural.",
  ui_story_5009_50090401_28_dialog_content = "Are you saying the Eclipsites can control the weather now?",
  ui_story_5009_50090401_29_dialog_content = "It's just my guess. I need more evidence.",
  ui_story_5009_50090401_30_dialog_content = "And there's something even more complicated.",
  ui_story_5009_50090401_31_dialog_content = "No time to talk now. I sense a big Eclipsite mob ahead.",
  ui_story_5009_50090401_32_dialog_content = "I'll lead. I shall dole out the proper judgment...",
  ui_story_5009_50090401_33_dialog_content = "And annihilate them all!",
  ui_story_5009_50090502_1_dialog_content = "All clear here! Let's head to the next spot.",
  ui_story_5009_50090502_2_dialog_content = "Wait, something's wrong!",
  ui_story_5009_50090502_3_dialog_content = "Who are you?",
  ui_story_5009_50090502_4_dialog_content = "You speak Universese, Eclipsite?",
  ui_story_5009_50090502_5_dialog_content = "You must be the nemesis my lord spoke of...",
  ui_story_5009_50090502_6_dialog_content = "Wow, Eclipsites can blab nonsense now too?",
  ui_story_5009_50090502_7_dialog_content = "Quite a lot of minions this time... It seems he came prepared.",
  ui_story_5009_50090502_8_dialog_content = "This is gonna be fun.",
  ui_story_5009_50090502_9_dialog_content = "Why are you staring into space, PlayerName?",
  ui_story_5009_50090502_10_dialog_content = "I just sensed a large horde of Eclipsites converging at the burial ground!",
  ui_story_5009_50090502_11_dialog_content = "Then we need to go there right now!",
  ui_story_5009_50090502_12_dialog_content = "No, they're all gone now.",
  ui_story_5009_50090502_13_dialog_content = "All gone?",
  ui_story_5009_50090502_14_dialog_content = "It just happened...",
  ui_story_5009_50090502_15_dialog_content = "A powerful energy was unleashed in the graveyard and then the Eclipsites were gone.",
  ui_story_5009_50090502_16_dialog_content = "I could sense it was Aurorian power...",
  ui_story_5009_50090502_17_dialog_content = "Is that Aurorian a friend... or a foe?",
  ui_story_5009_50090502_18_dialog_content = "I don't know yet, but this Aurorian can hide their energy fluctuations!",
  ui_story_5009_50090502_19_dialog_content = "Right now, I can't sense their presence.",
  ui_story_5009_50090502_20_dialog_content = "Why are they hiding...? Could they be some kind of unknown enemy?",
  ui_story_5009_50090502_21_dialog_content = "We have to be careful...",
  ui_story_5009_50090602_1_dialog_content = "Do you sense anything, PlayerName?",
  ui_story_5009_50090602_2_dialog_content = "The same Aurorian as before. Someone very powerful...",
  ui_story_5009_50090602_3_dialog_content = "Could it be Naroxel? She's powerful.",
  ui_story_5009_50090602_4_dialog_content = "I only brought Pittman with me.",
  ui_story_5009_50090602_5_dialog_content = "But you must know them.",
  ui_story_5009_50090602_6_dialog_content = "As I suspected, that Aurorian didn't come with you guys.",
  ui_story_5009_50090602_7_dialog_content = "Should we send someone to check it out?",
  ui_story_5009_50090602_8_dialog_content = "That's not necessary. I recall that Naroxel mentioned the Courier Union would send someone.",
  ui_story_5009_50090602_9_dialog_content = "Maybe it's a member of the Union.",
  ui_story_5009_50090602_10_dialog_content = "What are you discussing, soldiers?",
  ui_story_5009_50090602_11_dialog_content = "Lt. Vice, we were just talking about how Eraveil fought the Eclipsites in the past.",
  ui_story_5009_50090602_12_dialog_content = "There's an impenetrable Illumina line between Eraveil and the former Eclipsite lair.",
  ui_story_5009_50090602_13_dialog_content = "Eraveil's difficult terrain makes it easy to defend and hard for enemies to attack.",
  ui_story_5009_50090602_14_dialog_content = "But Caelestites cannot fight. What happened when they had to defend against the Eclipsites?",
  ui_story_5009_50090602_15_dialog_content = "They could sense Eclipsite movements and plan ahead of time.",
  ui_story_5009_50090602_16_dialog_content = "Illumina and Lumopolis often sent representatives as well as provisions to Eraveil.",
  ui_story_5009_50090602_17_dialog_content = "Yes, Eraveil is a tough nut to crack.",
  ui_story_5009_50090602_18_dialog_content = "But once you crack it, it's doomed.",
  ui_story_5009_50090602_19_dialog_content = "I'm sure you know the rest.",
  ui_story_5009_50090602_20_dialog_content = "How did Eclipsites get around the Illumina line and into Eraveil?",
  ui_story_5009_50090602_21_dialog_content = "There was a traitor among us.",
  ui_story_5009_50090602_22_dialog_content = "The more invulnerable your defense is, the more easily it is taken apart by betrayal.",
  ui_story_5009_50090602_23_dialog_content = "And there was an eclipse that day, so all defense systems went down.",
  ui_story_5009_50090701_1_dialog_content = "Is it me or is it very dark all of a sudden?",
  ui_story_5009_50090701_2_dialog_content = "It's supposed to be daytime, yet it's dark as night.",
  ui_story_5009_50090701_3_dialog_content = "An eclipse right as I mention one? How can this be?",
  ui_story_5009_50090701_4_dialog_content = "But judging from the crimson red halo in the sky, that's exactly what it is!",
  ui_story_5009_50090701_5_dialog_content = "This must be just a similar phenomenon, it has to be!",
  ui_story_5009_50090701_6_dialog_content = "Watch out, everybody, I sense an odd disturbance!",
  ui_story_5009_50090701_7_dialog_content = "Eraveil, eclipse...",
  ui_story_5009_50090701_8_dialog_content = "Is this a Caelestite's inevitable fate?",
  ui_story_5009_50090701_9_dialog_content = "Keep calm, PlayerName!",
  ui_story_5009_50090701_10_dialog_content = "Stop overthinking and focus on the present.",
  ui_story_5009_50090701_11_dialog_content = "You're right. I'm okay now.",
  ui_story_5009_50090701_12_dialog_content = "But could it be the person I sensed before?",
  ui_story_5009_50090701_13_dialog_content = "The one with concealment abilities?",
  ui_story_5009_50090701_14_dialog_content = "The dark sky, the scarlet corona.",
  ui_story_5009_50090701_15_dialog_content = "You're about to make a move...",
  ui_story_5009_50090701_16_dialog_content = "But this time, you'll not be spared!",
  ui_story_5009_50090702_1_dialog_content = "What's going on?!",
  ui_story_5009_50090702_2_dialog_content = "Gah!",
  ui_story_5009_50090702_3_dialog_content = "Don't panic! Kill the Eclipsite first!",
  ui_story_5009_50090702_4_dialog_content = "I somehow... can't use my full power, Carleen...",
  ui_story_5009_50090702_5_dialog_content = "I feel the same way.",
  ui_story_5009_50090702_6_dialog_content = "What about you, PlayerName?",
  ui_story_5009_50090702_7_dialog_content = "I'm fine, it's just...",
  ui_story_5009_50090702_8_dialog_content = "Just what?",
  ui_story_5009_50090702_9_dialog_content = "My psychic ability seems to have weakened. I can't sense what's going on in the distance.",
  ui_story_5009_50090702_10_dialog_content = "Our Luminatics are suppressed too.",
  ui_story_5009_50090702_11_dialog_content = "If I'm not wrong, it's due to the eclipse.",
  ui_story_5009_50090702_12_dialog_content = "Be on your toes, watch out for ambushing Eclipsites!",
  ui_story_5009_50090702_13_dialog_content = "I'm concerned about the group at the post... Let me try to reach them.",
  ui_story_5009_50090702_14_dialog_content = "Can't reach them at all!",
  ui_story_5009_50090702_15_dialog_content = "So communications are also down.",
  ui_story_5009_50090702_16_dialog_content = "Can we go meet up with Naroxel at the post?",
  ui_story_5009_50090702_17_dialog_content = "I'll lead the way.",
  ui_story_5009_50090702_18_dialog_content = "I can't sense what's going on from this distance, I'm worried that the Eclipsites will surround us...",
  ui_story_5009_50090702_19_dialog_content = "We'll cover for you, Lt. Vice.",
  ui_story_5009_50090702_20_dialog_content = "Okay, I'm counting on you.",
  ui_story_5009_50090702_21_dialog_content = "Let's go, PlayerName!",
  ui_story_5009_50090801_1_dialog_content = "Incoming blast!",
  ui_story_5009_50090801_2_dialog_content = "Watch out!",
  ui_story_5009_50090801_3_dialog_content = "Watch out!",
  ui_story_5009_50090801_4_dialog_content = "Too bad it missed.",
  ui_story_5009_50090801_5_dialog_content = "Are you ready?",
  ui_story_5009_50090801_6_dialog_content = "I'm coming to find you.",
  ui_story_5009_50090801_7_dialog_content = "Is everyone all right?",
  ui_story_5009_50090801_8_dialog_content = "I'm good. How about you, PlayerName?",
  ui_story_5009_50090801_9_dialog_content = "I'm fine.",
  ui_story_5009_50090801_10_dialog_content = "At this point I'm used to it.",
  ui_story_5009_50090801_11_dialog_content = "Where are we...?",
  ui_story_5009_50090801_12_dialog_content = "PlayerName, did you know such a strange place existed in Eraveil?",
  ui_story_5009_50090801_13_dialog_content = "No. I only have this strange feeling that my psychic abilities are...",
  ui_story_5009_50090801_14_dialog_content = "Are what? Are you hurt?",
  ui_story_5009_50090801_15_dialog_content = "Not at all. It's just... this feeling is hard to describe, it's like... like...",
  ui_story_5009_50090801_16_dialog_content = "Like my nose is all stuffed!",
  ui_story_5009_50090801_17_dialog_content = "Now's not the time for jokes!",
  ui_story_5009_50090801_18_dialog_content = "Sorry, but it's really how I feel.",
  ui_story_5009_50090801_19_dialog_content = "Unlike before, I can't use my power at all.",
  ui_story_5009_50090801_20_dialog_content = "If we can't rely on PlayerName's abilities...",
  ui_story_5009_50090801_21_dialog_content = "We'll have to be extra careful when fighting here.",
  ui_story_5009_50090801_22_dialog_content = "Watch out, Your Highness!",
  ui_story_5009_50090801_23_dialog_content = "!!!",
  ui_story_5009_50090801_24_dialog_content = "Too bad, I was so close to catching you...",
  ui_story_5009_50090801_25_dialog_content = "Your Highness, Carleen.",
  ui_story_5009_50090801_26_dialog_content = "Who are you?",
  ui_story_5009_50090801_27_dialog_content = "I'm so honored you asked for my name!",
  ui_story_5009_50090801_28_dialog_content = "I am...",
  ui_story_5009_50090801_A1_dialog_content = "Oh, I seem to have forgotten who I am.",
  ui_story_5009_50090801_29_dialog_content = "...",
  ui_story_5009_50090801_30_dialog_content = "No reaction?",
  ui_story_5009_50090801_31_dialog_content = "You should be yelling, \"What kind of joke is this?\" or \"Tell me who you are!\" at the top of your lungs at a time like this.",
  ui_story_5009_50090801_32_dialog_content = "How disgusting.",
  ui_story_5009_50090801_33_dialog_content = "Stop wasting your breath, Carleen.",
  ui_story_5009_50090801_34_dialog_content = "Just kill it!",
  ui_story_5009_50090801_35_dialog_content = "I just tried, Vice, but I still don't have my powers back.",
  ui_story_5009_50090801_36_dialog_content = "No problem. We'll handle the fighting!",
  ui_story_5009_50090801_37_dialog_content = "Vice, Pittman, cover me.",
  ui_story_5009_50090801_38_dialog_content = "Are you going to fight me?",
  ui_story_5009_50090801_39_dialog_content = "Oh, I'm so excited!",
  ui_story_5009_50090801_40_dialog_content = "Come, my Highness Carleen!",
  ui_story_5009_50090801_41_dialog_content = "Ice Blossom!",
  ui_story_5009_50090801_42_dialog_content = "Hmm...",
  ui_story_5009_50090801_43_dialog_content = "How come it didn't hurt one bit?",
  ui_story_5009_50090801_44_dialog_content = "Let's fight together, Carleen!",
  ui_story_5009_50090801_45_dialog_content = "Ah, this kind of fight...",
  ui_story_5009_50090801_46_dialog_content = "is so unsightly!",
  ui_story_5009_50090801_47_dialog_content = "!!!",
  ui_story_5009_50090801_48_dialog_content = "All of you were beaten so easily.",
  ui_story_5009_50090801_49_dialog_content = "You're no match for me in the least!",
  ui_story_5009_50090801_50_dialog_content = "What are you trying to say?",
  ui_story_5009_50090801_51_dialog_content = "Shh, don't interrupt. You disappoint me, Carleen.",
  ui_story_5009_50090801_52_dialog_content = "The way you fought was ugly and unbefitting for a princess.",
  ui_story_5009_50090801_53_dialog_content = "I was going to frame you as a beautiful painting, but now I've lost all interest.",
  ui_story_5009_50090801_54_dialog_content = "It's all your fault for ruining the Gautier vision.",
  ui_story_5009_50090801_55_dialog_content = "Gautier? The family name that was erased from the records?",
  ui_story_5009_50090801_56_dialog_content = "Other than Beryl Gautier, there's only...",
  ui_story_5009_50090801_57_dialog_content = "You must be Mirren Gautier!",
  ui_story_5009_50090801_58_dialog_content = "Wow, someone here recognizes me?",
  ui_story_5009_50090801_59_dialog_content = "You were on my blacklist for a long time. I did not expect that today would be the day that I would finally run into you.",
  ui_story_5009_50090801_60_dialog_content = "You're a refugee and a traitor!",
  ui_story_5009_50090801_61_dialog_content = "Don't get so worked up! At least not before thanking me for announcing my name!",
  ui_story_5009_50090801_62_dialog_content = "Mirren... Gautier?",
  ui_story_5009_50090801_63_dialog_content = "Yes, Your Highness. Mirren Gautier, the mastermind behind the Pyrrhus and Gautier insurrection!",
  ui_story_5009_50090801_64_dialog_content = "So he's from Lumopolis?",
  ui_story_5009_50090801_65_dialog_content = "The way he looks now, he looks odd even by Eclipsite standards.",
  ui_story_5009_50090801_66_dialog_content = "Another Lumopolis and Aurorian traitor...",
  ui_story_5009_50090801_67_dialog_content = "Accept your judgment, Mirren Gautier!",
  ui_story_5009_50090801_68_dialog_content = "I hope you're not just paying lip service.",
  ui_story_5009_50090801_69_dialog_content = "I'll hold him off, you go find an exit, PlayerName!",
  ui_story_5009_50090801_70_dialog_content = "Everyone follow PlayerName. I'll cover the rear.",
  ui_story_5009_50090801_71_dialog_content = "Say, where are you going?",
  ui_story_5009_50090801_72_dialog_content = "Fooey, they took off...",
  ui_story_5009_50090801_73_dialog_content = "Accept your judgment, outlaw!",
  ui_story_5009_50090801_74_dialog_content = "Your attempts are futile. Do you think such weak attacks would have any effect on me?",
  ui_story_5009_50090801_75_dialog_content = "This is ridiculous.",
  ui_story_5009_50090801_76_dialog_content = "I've decided to make you suffer until you die, then do the same to them.",
  ui_story_5009_50090801_77_dialog_content = "But let me offer you some friendly advice first...",
  ui_story_5009_50090801_78_dialog_content = "That useless Caelestite punk will never find the way out of here.",
  ui_story_5009_50090801_79_dialog_content = "This is the might of the Eclipse!",
  ui_story_5009_50090801_80_dialog_content = "I see your legs aren't the only thing that got messed up during the transformation process...",
  ui_story_5009_50090801_81_dialog_content = "but your eyeballs and head too!",
  ui_story_5009_50090801_82_dialog_content = "Hahahaha, well. Your body's the one that's going to get messed up soon!",
  ui_story_5009_50090801_83_dialog_content = "Vice, Carleen, I think we've reached the end!",
  ui_story_5009_50090801_84_dialog_content = "Yes, I can feel an invisible wall.",
  ui_story_5009_50090801_85_dialog_content = "Stand aside, PlayerName.",
  ui_story_5009_50090801_86_dialog_content = "Hit the same spot with me, Vice.",
  ui_story_5009_50090801_87_dialog_content = "Roger! Rapid Torrent!",
  ui_story_5009_50090801_88_dialog_content = "We clearly hit, but no sign of damage at all.",
  ui_story_5009_50090801_89_dialog_content = "Look for anything unusual nearby that could be an exit.",
  ui_story_5009_50090801_90_dialog_content = "Nope, haven't seen any.",
  ui_story_5009_50090801_91_dialog_content = "Is there really an exit in this weird dimension?",
  ui_story_5009_50090801_92_dialog_content = "Drat...",
  ui_story_5009_50090801_93_dialog_content = "I can sense everything else normally, I can even hear the sound of their fight.",
  ui_story_5009_50090801_94_dialog_content = "But I can't get my psychic ability going!",
  ui_story_5009_50090801_95_dialog_content = "I'm afraid Pittman won't last long on his own. If things carry on this way...",
  ui_story_5009_50090801_96_dialog_content = "What, you only got this far?",
  ui_story_5009_50090801_97_dialog_content = "Where's Pittman?",
  ui_story_5009_50090801_98_dialog_content = "How can he manage to stop me with such a feeble attempt?",
  ui_story_5009_50090801_99_dialog_content = "Oh, there he is, hobbling over this way right now. Isn't that comical?",
  ui_story_5009_50090801_100_dialog_content = "You're hurt, Pittman!",
  ui_story_5009_50090801_101_dialog_content = "Cough... I can still fight... Don't worry about me...",
  ui_story_5009_50090801_102_dialog_content = "Very good!",
  ui_story_5009_50090801_103_dialog_content = "Now, shall we continue the game?",
  ui_story_5009_50090801_104_dialog_content = "Haha!",
  ui_story_5009_50090901_1_dialog_content = "Tracking Strike!",
  ui_story_5009_50090901_2_dialog_content = "Huh? Oh, when it comes to sneak attacks...",
  ui_story_5009_50090901_3_dialog_content = "I truly am an expert.",
  ui_story_5009_50090901_4_dialog_content = "Ugh...",
  ui_story_5009_50090901_5_dialog_content = "Mirren could still use Lumopolis Luminatics, how can this be?",
  ui_story_5009_50090901_6_dialog_content = "How are you holding up, Vice?",
  ui_story_5009_50090901_7_dialog_content = "Let me try!",
  ui_story_5009_50090901_8_dialog_content = "Never say that until you can fight much better than they do.",
  ui_story_5009_50090901_9_dialog_content = "That's my kind advice for you, Caelestite.",
  ui_story_5009_50090901_10_dialog_content = "You initiated the eclipse and trapped us in the pocket dimension...",
  ui_story_5009_50090901_11_dialog_content = "Oh, those are the extraordinary abilities granted by the great master, freeing me to my own fate!",
  ui_story_5009_50090901_12_dialog_content = "Blah, blah, blah. It's nothing more than transformation, and not new to us, either. Schummer, for one...",
  ui_story_5009_50090901_13_dialog_content = "Oh, you're a fun one, little Caelestite.",
  ui_story_5009_50090901_14_dialog_content = "My esteemed Aurorian guests, are you truly expecting a Caelestite to save you with words?",
  ui_story_5009_50090901_15_dialog_content = "You've talked too much!",
  ui_story_5009_50090901_16_dialog_content = "Leave the fighting to me, PlayerName. You find the way out.",
  ui_story_5009_50090901_17_dialog_content = "Hey, just a minute here. You still don't have any idea what's going on, do you?",
  ui_story_5009_50090901_18_dialog_content = "This is my world.",
  ui_story_5009_50090901_19_dialog_content = "Kindly remind you that it's not wise to oppose me here.",
  ui_story_5009_50090901_20_dialog_content = "Nonsense!",
  ui_story_5009_50090901_21_dialog_content = "This is Eraveil and it doesn't belong to you!",
  ui_story_5009_50090901_22_dialog_content = "I cannot tolerate your actions here!",
  ui_story_5009_50090901_23_dialog_content = "Really? Why don't you show me what you got?",
  ui_story_5009_50090901_24_dialog_content = "If you put up a good effort, I'll consider granting a quick death.",
  ui_story_5009_50090901_25_dialog_content = "Now, never say I didn't give you a chance! How does that sound, Carleen? Oops, forgive my rudeness.",
  ui_story_5009_50090901_26_dialog_content = "However... Hmm...",
  ui_story_5009_50090901_27_dialog_content = "Should I address you as Your Highness or Captain?",
  ui_story_5009_50090901_28_dialog_content = "You're not fit to call her by either title!",
  ui_story_5009_50090901_29_dialog_content = "You betrayer of Light, breaker of Lumopolis laws... *Coughs*",
  ui_story_5009_50090901_30_dialog_content = "You're hurting, Pittman!",
  ui_story_5009_50090901_31_dialog_content = "Traitors never end well, Mirren Gautier.",
  ui_story_5009_50090901_32_dialog_content = "My lance shall be your verdict.",
  ui_story_5009_50090901_33_dialog_content = "Whoa, I apologize, Carleen, ole personification of righteousness!",
  ui_story_5009_50090901_34_dialog_content = "I see how wrong I was. Should I get on my knees and repent?",
  ui_story_5009_50090901_35_dialog_content = "I didn't do it on purpose, really... Hahaha!",
  ui_story_5009_50090901_36_dialog_content = "Die, Mirren Gautier!",
  ui_story_5009_50090901_37_dialog_content = "Gautier, Gautier, Gautier...",
  ui_story_5009_50090901_38_dialog_content = "Why does this name sound so distasteful coming out of your mouth?",
  ui_story_5009_50090901_39_dialog_content = "Gautier is a noble surname handed down from generation to generation in Lumopolis, unworthy of belonging to someone like you!",
  ui_story_5009_50090901_40_dialog_content = "Oh really? Yet the Gautiers have long been under the thumb of you Schwartzes... No, make that the great Lumopolis.",
  ui_story_5009_50090901_41_dialog_content = "My family, our name, our glory... You ruined it for no reason at all long ago...",
  ui_story_5009_50090901_42_dialog_content = "Nonsense!",
  ui_story_5009_50090901_43_dialog_content = "Lumopolis treated the Gautiers and Pyrrhuses with kid gloves following the insurgence.",
  ui_story_5009_50090901_44_dialog_content = "Until they were finally forced to adopt extreme measures.",
  ui_story_5009_50090901_45_dialog_content = "You deserved what you got.",
  ui_story_5009_50090901_46_dialog_content = "Is that what you read in the textbooks, dear princess?",
  ui_story_5009_50090901_47_dialog_content = "I'm not surprised, since the history of Lumopolis, like you...",
  ui_story_5009_50090901_48_dialog_content = "It is easily malleable by others.",
  ui_story_5009_50090901_49_dialog_content = "Let's not waste our breath on this scum, Your Highness.",
  ui_story_5009_50090901_50_dialog_content = "More precisely, this is the insurrection mastermind and a wanted felon.",
  ui_story_5009_50090901_51_dialog_content = "Come now, Your Honor! Do you think you're in your holier-than-thou court of law?",
  ui_story_5009_50090901_52_dialog_content = "Would you like me to kneel and atone as well?",
  ui_story_5009_50090901_53_dialog_content = "You talk too much, Mirren!",
  ui_story_5009_50090901_54_dialog_content = "This felon probably kept it bottled up for too long and was just waiting for a chance to vent.",
  ui_story_5009_50090901_55_dialog_content = "Sounds like a villain who's been wronged. But where have I seen it before...?",
  ui_story_5009_50090901_56_dialog_content = "Vent? Wronged? No, no, no.",
  ui_story_5009_50090901_57_dialog_content = "Though the Gautiers wronged and killed by Lumopolis should be able to vent to you soon enough.",
  ui_story_5009_50090901_58_dialog_content = "Save for our noble Carleen, the rest of you have to die.",
  ui_story_5009_50090901_59_dialog_content = "Shameless traitor! You started the rebellion! You're the true murderer!",
  ui_story_5009_50090901_60_dialog_content = "Is that the conclusion or verdict, Your Honor?",
  ui_story_5009_50090901_61_dialog_content = "Heh, judgment is meaningless without true power.",
  ui_story_5009_50090901_62_dialog_content = "You can ask my people for the truth once you're dead.",
  ui_story_5009_50090901_63_dialog_content = "Now, I shall give you...",
  ui_story_5009_50090901_64_option_content = "Blast incoming!",
  ui_story_5009_50090901_65_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5009_50090901_66_dialog_content = "What the...?",
  ui_story_5009_50090901_67_dialog_content = "Break it up!",
  ui_story_5009_50090901_68_dialog_content = "Argh!",
  ui_story_5009_50090901_69_dialog_content = "Is everyone all right?",
  ui_story_5009_50090901_70_dialog_content = "I'm here, PlayerName. Everyone's fine.",
  ui_story_5009_50090901_71_dialog_content = "We're out!",
  ui_story_5009_50090901_72_dialog_content = "Your Luminatics is truly amazing, Captain Carleen.",
  ui_story_5009_50090901_73_dialog_content = "It wasn't me.",
  ui_story_5009_50090901_74_dialog_content = "Stay alert, we're still under the eclipse.",
  ui_story_5009_50090901_75_dialog_content = "What was that, PlayerName?",
  ui_story_5009_50090901_76_dialog_content = "I sensed the Aurorian who was at the graveyard.",
  ui_story_5009_50090901_77_dialog_content = "So, the Aurorian in the battle just now...",
  ui_story_5009_50090901_78_dialog_content = "Right! That huge sudden burst of energy just now must've been from that very same Aurorian!",
  ui_story_5009_50090901_79_dialog_content = "It penetrated the dimensional barrier and struck Mirren.",
  ui_story_5009_50090901_80_dialog_content = "I've never seen any offense like that. That Aurorian has terrifying concealment and destructive powers!",
  ui_story_5009_50090901_81_dialog_content = "You've never seen any Luminatics like that, either?",
  ui_story_5009_50090901_82_dialog_content = "Heh, can't believe I got a compliment out of her highness Carleen!",
  ui_story_5009_50090901_83_dialog_content = "Who are you?",
  ui_story_5009_50090901_84_dialog_content = "*Coughs* ... Figured it was you.",
  ui_story_5009_50090901_85_dialog_content = "Allow me to introduce. This lady is from the Lumopolis...",
  ui_story_5009_50090901_86_dialog_content = "No, wait, make that from the True Order, Paloma Py...",
  ui_story_5009_50090901_87_dialog_content = "Paloma Pyrrhus? From the House of Pyrrhus?",
  ui_story_5009_50090901_88_dialog_content = "You sure are astute and observant, Your Honor!",
  ui_story_5009_50090901_89_dialog_content = "Aren't you excited to see two wanted felons from two rebel houses on the same day?",
  ui_story_5009_50090901_90_dialog_content = "You're Paloma Pyrrhus? How can you be a Pyrrhus? I thought Caroline...",
  ui_story_5009_50090901_91_dialog_content = "Call me Paloma, Your Highness.",
  ui_story_5009_50090901_92_dialog_content = "It is you, Paloma! You changed a lot.",
  ui_story_5009_50090901_93_dialog_content = "Okay, I'm getting really confused now...",
  ui_story_5009_50090901_94_dialog_content = "House of Pyrrhus and House of Gautier are co-conspirators, PlayerName, which makes Paloma here...",
  ui_story_5009_50090901_95_dialog_content = "Let us not forget, Your Honor...",
  ui_story_5009_50090901_96_dialog_content = "Paloma here is not only a member of the insurgent House of Pyrrhus, but a former nun who turned her back on the Light.",
  ui_story_5009_50090901_97_dialog_content = "If I'm correct, she's on your so-called blacklist of wanted too, right? Shouldn't you be apprehending her, righteous warriors?",
  ui_story_5009_50090901_98_dialog_content = "How Lumopolis enforces its law is none of your business.",
  ui_story_5009_50090901_99_dialog_content = "It's such a bore listening to all of you bicker.",
  ui_story_5009_50090901_100_dialog_content = "Mirren Gautier must die. Anything else, I don't care about.",
  ui_story_5009_50090901_101_dialog_content = "I knew Mirren started all this!",
  ui_story_5009_50090901_102_dialog_content = "But how did the House of Pyrrhus get involved?",
  ui_story_5009_50090901_103_dialog_content = "You can continue your inquiry as you like, Your Honor.",
  ui_story_5009_50090901_104_dialog_content = "But I'm here for revenge, not building a case.",
  ui_story_5009_50090901_105_dialog_content = "Oh, it's so touching when old friends reunite.",
  ui_story_5009_50090901_106_dialog_content = "How many times do I have to tell you, Paloma, that the powers-that-be in Lumopolis are the ones who killed your people!",
  ui_story_5009_50090901_107_dialog_content = "The arrogant, cocky Carleen Schwartz should be the one you're after here!",
  ui_story_5009_50090901_108_dialog_content = "Of course, the honorable judge too.",
  ui_story_5009_50090901_109_dialog_content = "It seems we have a different understanding of mastermind.",
  ui_story_5009_50090901_110_dialog_content = "But then, you can't expect an Eclipsite to wholly comprehend the Aurorian language.",
  ui_story_5009_50090901_111_dialog_content = "Don't go against me!",
  ui_story_5009_50090901_112_dialog_content = "This is your last chance.",
  ui_story_5009_50090901_113_dialog_content = "Exact vengeance against Lumopolis with me, or die alongside them. Pick one.",
  ui_story_5009_50090901_114_dialog_content = "I see only death can cure you and curb your verbosity.",
  ui_story_5009_50090901_115_dialog_content = "Cure? That actually enlightened me to the fact that I don't have to kill you...",
  ui_story_5009_50090901_116_dialog_content = "The great master would be delighted that I delivered a new toy.",
  ui_story_5009_50090901_117_dialog_content = "A powerful, beautiful Aurorian woman.",
  ui_story_5009_50090901_118_dialog_content = "Hmm. Like to see you try.",
  ui_story_5009_50090901_119_dialog_content = "What's going on here? Is Paloma helping us fight?",
  ui_story_5009_50090901_120_dialog_content = "She is powerful. Mirren might not win.",
  ui_story_5009_50090901_121_dialog_content = "Paloma is high on the most dangerous list of the church. She completely turned her back on the Light to join the True Order.",
  ui_story_5009_50090901_122_dialog_content = "The True Order... It appears Paloma has learned special Luminatics from them.",
  ui_story_5009_50090901_123_dialog_content = "Luminatics that wasn't affected by the eclipse and was powerful enough to break the dimension barrier.",
  ui_story_5009_50090901_124_dialog_content = "Wait, I think the conversation between Paloma and that Eclipsite is about...",
  ui_story_5009_50090901_125_dialog_content = "Hey, are you going to stop talking or what?",
  ui_story_5009_50090901_126_dialog_content = "Mirren has got backup coming, and I'm not here to bodyguard you!",
  ui_story_5009_50090901_127_dialog_content = "Ice Blossom! Spread out!",
  ui_story_5009_50090901_128_dialog_content = "This is bad, I'm sensing Eclipsites closing in on us...",
  ui_story_5009_50090901_129_dialog_content = "That's okay, our backups are here too!",
  ui_story_5009_50090901_130_dialog_content = "Can you still coordinate, PlayerName?",
  ui_story_5009_50090901_131_dialog_content = "I got this!",
  ui_story_5009_50090902_1_dialog_content = "Are we really going to fight, Lady Pyrrhus?",
  ui_story_5009_50090902_2_dialog_content = "Rehashing the same lines, Mr. Gautier?",
  ui_story_5009_50090902_3_dialog_content = "This is different, seeing that two traitors of Lumopolis are fighting before its powers-that-be.",
  ui_story_5009_50090902_4_dialog_content = "Who do you think will benefit the most?",
  ui_story_5009_50090902_5_dialog_content = "I got plenty of time to think about that once you're dead.",
  ui_story_5009_50090902_6_dialog_content = "We soften each other up for them to enforce so-called justice at the end. Great.",
  ui_story_5009_50090902_7_dialog_content = "If we died, that would truly be the end of the bloodline of Gautiers and Pyrrhuses!",
  ui_story_5009_50090902_8_dialog_content = "We both tasted the justice of Lumopolis, Paloma.",
  ui_story_5009_50090902_9_dialog_content = "The deeds of Pyrrhuses have brought shame to Lumopolis, please forgive us, God of Light.",
  ui_story_5009_50090902_10_dialog_content = "We're willing to accept the punishment in return for your mercy.",
  ui_story_5009_50090902_11_dialog_content = "The pain of losing Lumina powers shall always serve as a reminder not to commit evil...",
  ui_story_5009_50090902_12_dialog_content = "<color=#e8d9bb>Knock, knock!</color>",
  ui_story_5009_50090902_13_dialog_content = "Exile Settlement 14, anybody in? I'm a messenger from Lumopolis.",
  ui_story_5009_50090902_14_dialog_content = "Open the door and sign for it, Paloma.",
  ui_story_5009_50090902_15_dialog_content = "Sure, father.",
  ui_story_5009_50090902_16_dialog_content = "<color=#e8d9bb>Creak...</color>",
  ui_story_5009_50090902_17_dialog_content = "Life in Lower Lumopolis has been difficult over the past year. We have all suffered...",
  ui_story_5009_50090902_18_dialog_content = "It was clearly their fault, so why do we have to suffer too?",
  ui_story_5009_50090902_19_dialog_content = "I don't mind if it's just the two of us, but our child...",
  ui_story_5009_50090902_20_dialog_content = "So what? The worst scenario is we quit the church, lose Lumina powers, and live like commoners.",
  ui_story_5009_50090902_21_dialog_content = "But kidnapping Gautier children for transformation is a major sin, not a misdemeanor.",
  ui_story_5009_50090902_22_dialog_content = "But... But what's that got to do with us?",
  ui_story_5009_50090902_23_dialog_content = "The Schwartzes never cared about other nobles.",
  ui_story_5009_50090902_24_dialog_content = "Be quiet, you!",
  ui_story_5009_50090902_25_dialog_content = "Do you know even the innocent Gautiers have been banished to Lower Lumopolis?",
  ui_story_5009_50090902_26_dialog_content = "Wh-Wh-What are you talking about!?",
  ui_story_5009_50090902_27_dialog_content = "Just resign yourself to fate. Be happy we're still alive.",
  ui_story_5009_50090902_28_dialog_content = "...",
  ui_story_5009_50090902_29_dialog_content = "Father, mother, do you know Mirren Gautier?",
  ui_story_5009_50090902_30_dialog_content = "Mirren?",
  ui_story_5009_50090902_31_dialog_content = "Isn't that the painter of some renown from the House of Gautier?",
  ui_story_5009_50090902_32_dialog_content = "Why do you ask, Paloma?",
  ui_story_5009_50090902_33_dialog_content = "This is a notice we've just received from the Hall of Justice. It says that Mirren Gautier is a dangerous element.",
  ui_story_5009_50090902_34_dialog_content = "If you see this person, report him to the authorities right away.",
  ui_story_5009_50090902_35_dialog_content = "Really? Your uncle spoke to me about him a few days ago.",
  ui_story_5009_50090902_36_dialog_content = "My brother mentioned this name when we chatted yesterday, too.",
  ui_story_5009_50090902_37_dialog_content = "I have a bad feeling about this. We all should tread lightly.",
  ui_story_5009_50090902_38_dialog_content = "Got it, fa...",
  ui_story_5009_50090902_39_dialog_content = "<color=#e8d9bb>Knock, knock!</color>",
  ui_story_5009_50090902_40_dialog_content = "Hurry, hurry...",
  ui_story_5009_50090902_41_dialog_content = "Run, the Lumopolis Army has surrounded the settlement!",
  ui_story_5009_50090902_42_dialog_content = "What?",
  ui_story_5009_50090902_43_dialog_content = "Slow down, take it easy.",
  ui_story_5009_50090902_44_dialog_content = "Mirren Gautier is usurping. Both the army and the church are on the march!",
  ui_story_5009_50090902_45_dialog_content = "The House of Gautier? Uprising?",
  ui_story_5009_50090902_46_dialog_content = "The church? Why would the church react?",
  ui_story_5009_50090902_47_dialog_content = "Mirren allegedly used transformation, and the Pyrrhuses and Eclipsites have been implicated in the insurrection.",
  ui_story_5009_50090902_48_dialog_content = "I got to go. You should run too.",
  ui_story_5009_50090902_49_dialog_content = "And this has something to do with us, again!",
  ui_story_5009_50090902_50_dialog_content = "If I know Lumopolis like I do, this is going to be a grand-scale persecution.",
  ui_story_5009_50090902_51_dialog_content = "As a Pyrrhus, we need not worry as long as we're fairly judged.",
  ui_story_5009_50090902_52_dialog_content = "You're too idealistic, my child...",
  ui_story_5009_50090902_53_dialog_content = "Listen to me and hide. I'll check it out with your mother.",
  ui_story_5009_50090902_54_dialog_content = "Come with me now, Paloma. Nobody's leaving if we wait any longer.",
  ui_story_5009_50090902_55_dialog_content = "Go!",
  ui_story_5009_50090902_56_dialog_content = "By the lord's decree, kill the traitors! By the lord's decree, kill the traitors!",
  ui_story_5009_50090902_57_dialog_content = "Why are they fighting? And where did the monsters come from?",
  ui_story_5009_50090902_58_dialog_content = "Huh?! These are all our people! Eclipsites... They've been transformed into Eclipsites!",
  ui_story_5009_50090902_59_dialog_content = "It's over... This is the end of the Pyrrhuses.",
  ui_story_5009_50090902_60_dialog_content = "Punish the rebels! Punish the rebels! Punish the rebels!",
  ui_story_5009_50090902_62_dialog_content = "The justice of Lumopolis... Hah! I have plenty of experience with that.",
  ui_story_5009_50090902_63_dialog_content = "*Cough* Then... call off your attack...",
  ui_story_5009_50090902_64_dialog_content = "Everything can be traced back to Lumopolis...",
  ui_story_5009_50090902_65_dialog_content = "Very well, Mirren Gautier. Once you're dead, I'll make sure to send the mayor along to keep you company.",
  ui_story_5009_50090902_66_dialog_content = "But first things first... It's time to die.",
  ui_story_5009_50090902_67_dialog_content = "Miss Paloma Pyrrhus... If this is how it ends, all I can do is to bury you properly, with those righteous warriors.",
  ui_story_5009_50090902_68_dialog_content = "Your words are as hyperbolic as ever...",
  ui_story_5009_50091001_1_dialog_content = "Drat... My psychic abilities still haven't fully recovered...",
  ui_story_5009_50091001_2_dialog_content = "It's okay, PlayerName! Your commands were still precise just now!",
  ui_story_5009_50091001_3_dialog_content = "What about the monster? Where did it go?",
  ui_story_5009_50091001_4_dialog_content = "It's still nearby! But its power seems to be... growing?",
  ui_story_5009_50091001_5_dialog_content = "But Paloma's earlier attack seriously injured it! We all saw it! Unless...",
  ui_story_5009_50091001_6_dialog_content = "It appears to be devouring the nearby Eclipsites to regain its Darkflow.",
  ui_story_5009_50091001_7_dialog_content = "Ugh... Not again! It's disgusting!",
  ui_story_5009_50091001_8_dialog_content = "Did you hear that, Paloma?",
  ui_story_5009_50091001_9_dialog_content = "That monster is still lurking somewhere nearby! Stay on your guard!",
  ui_story_5009_50091001_10_dialog_content = "Just worry about yourselves, and stay out of my way.",
  ui_story_5009_50091001_11_dialog_content = "A wave of Darkflow!!",
  ui_story_5009_50091001_12_dialog_content = "Oh no, it's coming from Paloma's direction! The monster is making its attack!",
  ui_story_5009_50091001_13_dialog_content = "This is bad...",
  ui_story_5009_50091001_14_option_content = "Force Boost",
  ui_story_5009_50091001_15_dialog_content = "Paloma! Dodge towards your front left!",
  ui_story_5009_50091001_16_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5009_50091001_17_dialog_content = "Are... Are you okay, Paloma?",
  ui_story_5009_50091001_18_dialog_content = "*cough, cough* Is this... the power of the Caelestites?",
  ui_story_5009_50091001_19_dialog_content = "Instantly transmitting thoughts to my mind...",
  ui_story_5009_50091001_20_dialog_content = "Shouldn't you ask for permission first?",
  ui_story_5009_50091001_21_dialog_content = "If it wasn't for PlayerName forced the power to help you dodge...",
  ui_story_5009_50091001_22_dialog_content = "Mirren's ambush would have succeeded.",
  ui_story_5009_50091001_23_dialog_content = "Mirren... sneaks around and attacks like a rat.",
  ui_story_5009_50091001_24_dialog_content = "Hah! I like that attitude of yours, little miss Illumina!",
  ui_story_5009_50091001_25_dialog_content = "I'm fine, so don't worry about me!",
  ui_story_5009_50091001_26_dialog_content = "We have to do everything we can to find him, before he escapes!",
  ui_story_5009_50091001_27_dialog_content = "If you can't attack, run away. Typical Mirren Gautier style.",
  ui_story_5009_50091001_28_dialog_content = "You seem to know him well, Paloma.",
  ui_story_5009_50091001_29_dialog_content = "Hmph... All I know about him is his cowardly approach to combat.",
  ui_story_5009_50091002_1_dialog_content = "The Gautier and Pyrrhus families, rebelled against the authority and conspired with the Eclipsites! Never forget their betrayal!",
  ui_story_5009_50091002_2_dialog_content = "Punish the rebels! Slaughter the Eclipsites!",
  ui_story_5009_50091002_3_dialog_content = "Everyone, please! We are nothing more than kinsmen of the Pyrrhus family! Please understand!",
  ui_story_5009_50091002_4_dialog_content = "Yours is a family of rebellious traitors, ones who dared to conspire with the Eclipsites and use their techniques, no less! You deserve no mercy!",
  ui_story_5009_50091002_5_dialog_content = "If this has to do with the crystal experiments... We have already been punished for that matter, officer!",
  ui_story_5009_50091002_6_dialog_content = "We were deprived of our Lumina, and cast away into the Lower Lumopolis...",
  ui_story_5009_50091002_7_dialog_content = "We pray to the God of Light every day, begging for forgiveness... I assure you that this is the truth!",
  ui_story_5009_50091002_8_dialog_content = "Those transformed Eclipsites just now... They were members of the Pyrrhus family!",
  ui_story_5009_50091002_9_dialog_content = "We... we are not like them...",
  ui_story_5009_50091002_10_dialog_content = "We haven't been transformed!",
  ui_story_5009_50091002_A1_dialog_content = "You're guilty, every last one of you! Guards! Get them!",
  ui_story_5009_50091002_11_dialog_content = "Father! Mother! What's going on here?",
  ui_story_5009_50091002_12_dialog_content = "Paloma...?! Run, Paloma! Run away!!",
  ui_story_5009_50091002_13_dialog_content = "Father? Mother...!",
  ui_story_5009_50091002_14_dialog_content = "Paloma... Come with me, hurry!",
  ui_story_5009_50091002_15_dialog_content = "Urgh...",
  ui_story_5009_50091002_16_dialog_content = "Stay away from her!",
  ui_story_5009_50091002_17_dialog_content = "Are you mad, woman?! How dare you bite me!",
  ui_story_5009_50091002_18_dialog_content = "You lot! Go after the girl!",
  ui_story_5009_50091002_19_dialog_content = "Yes, sir!",
  ui_story_5009_50091002_20_dialog_content = "Paloma, please... You have to eat something.",
  ui_story_5009_50091002_21_dialog_content = "Why...? What are all of these for...?",
  ui_story_5009_50091002_22_dialog_content = "Father... Mother... Will they be okay...?",
  ui_story_5009_50091002_23_dialog_content = "It's been three days, Paloma. You need to give yourself time to rest.",
  ui_story_5009_50091002_24_dialog_content = "Ah... You... You're back... Have you learned anything about my parents?",
  ui_story_5009_50091002_25_dialog_content = "I... I've only heard bad news. If you wish to hear it, you'll need to prepare yourself mentally.",
  ui_story_5009_50091002_26_dialog_content = "Our kinsfolk have been all but massacred by the Lumopolis forces, along with...",
  ui_story_5009_50091002_27_dialog_content = "...",
  ui_story_5009_50091002_28_dialog_content = "Surely, you understand what I'm trying to tell you... right?",
  ui_story_5009_50091002_29_dialog_content = "I have no idea where Mirren Gautier learned those techniques, but he kidnapped a number of our relatives and experimented on them.",
  ui_story_5009_50091002_30_dialog_content = "Shortly afterwards, the Gautier family began their rebellion.",
  ui_story_5009_50091002_31_dialog_content = "They transformed... our family members? Were they taking revenge on the Pyrrhus family?",
  ui_story_5009_50091002_32_dialog_content = "Not entirely. They believe themselves to be the victims, and that they were all exiled as the same by the authorities.",
  ui_story_5009_50091002_33_dialog_content = "I imagine their animosity towards the nobility of Lumopolis played no small part in their rebellion.",
  ui_story_5009_50091002_34_dialog_content = "In any case, this massacre was another case of Lumopolis' indiscriminate punishment. For the nobles, this is the most thorough answer to their problems.",
  ui_story_5009_50091002_35_dialog_content = "So there's no real truth or justice to it...?",
  ui_story_5009_50091002_36_dialog_content = "The truth is... far too complicated, and would tarnish the reputations of the nobility.",
  ui_story_5009_50091002_37_dialog_content = "As for justice? Well... our entire family has been wiped out. As far as the outsiders are concerned, this is justice.",
  ui_story_5009_50091002_38_dialog_content = "Then what about us? We're innocent!",
  ui_story_5009_50091002_39_dialog_content = "The forces of destiny saw fit to let us survive. Thinking on it too much will serve us no purpose.",
  ui_story_5009_50091002_40_dialog_content = "No... This isn't right. This can't be... This isn't justice, at all.",
  ui_story_5009_50091002_41_dialog_content = "The most ironic part is that even though both the Gautier and Pyrrhus families have been exterminated, Mirren is still out there, they can't get to him.",
  ui_story_5009_50091002_42_dialog_content = "Mirren Gautier... He isn't much older than you now.",
  ui_story_5009_50091002_43_dialog_content = "He was just a boy who loved to draw... I cannot fathom how does he obtain such knowledge.",
  ui_story_5009_50091002_44_dialog_content = "He's still not dead? Good... I know what I have to do now.",
  ui_story_5009_50091002_45_dialog_content = "Well, think about your parents. I'm sure they both wish you a happy life.",
  ui_story_5009_50091002_46_dialog_content = "Mother... Father...",
  ui_story_5009_50091002_47_dialog_content = "Have you forgotten? You can't even beat the most junior of guards now.",
  ui_story_5009_50091002_48_dialog_content = "You mean, without Luminatics, I can't even...",
  ui_story_5009_50091002_49_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5009_50091002_50_dialog_content = "Punish the rebels! Slaughter the Eclipsites!",
  ui_story_5009_50091002_51_dialog_content = "This place is harboring fugitives of the Pyrrhus family! Hunt them down!",
  ui_story_5009_50091002_52_dialog_content = "Run, Paloma!",
  ui_story_5009_50091002_53_dialog_content = "Not without you!",
  ui_story_5009_50091002_54_dialog_content = "You have to live on, Paloma! To avenge us... You have to survive!",
  ui_story_5009_50091101_1_dialog_content = "Don't let your guards down, everyone! Stay alert!",
  ui_story_5009_50091101_2_dialog_content = "But I don't sense any more Eclipsites nearby...",
  ui_story_5009_50091101_3_dialog_content = "It's fine... He's just reminding everyone to be cautious of me.",
  ui_story_5009_50091101_4_dialog_content = "After all, I'm a fugitive of the traitorous Pyrrhus family, and a member of the blasphemous True Order. By all accounts, I'm highly dangerous and not to be trusted.",
  ui_story_5009_50091101_5_dialog_content = "If you had any ill intent towards us, you could have killed us all with your destructive powers before we even know.",
  ui_story_5009_50091101_6_dialog_content = "...Alright, that's enough. Let's go find Mirren!",
  ui_story_5009_50091101_7_dialog_content = "The Eclipse hasn't dissipated yet, so he should still be nearby.",
  ui_story_5009_50091101_8_dialog_content = "I'll try to sense him again.",
  ui_story_5009_50091101_9_dialog_content = "You don't have to overexert yourself, PlayerName.",
  ui_story_5009_50091101_10_dialog_content = "I'll be fine, Vice. It's under my control.",
  ui_story_5009_50091101_11_dialog_content = "If you can find him, I have a way to finish him off.",
  ui_story_5009_50091101_12_option_content = "Sense",
  ui_story_5009_50091101_13_dialog_content = "Paloma! Run!",
  ui_story_5009_50091101_A2_dialog_content = "Run!!!",
  ui_story_5009_50091101_14_dialog_content = "Father? Mother...!",
  ui_story_5009_50091101_A1_dialog_content = "Paloma... Come with me! Hurry!",
  ui_story_5009_50091101_15_dialog_content = "Urgh...",
  ui_story_5009_50091101_16_dialog_content = "Stay away from her!",
  ui_story_5009_50091101_17_dialog_content = "Are you mad, woman?! How dare you bite me!",
  ui_story_5009_50091101_18_dialog_content = "P... Paloma...",
  ui_story_5009_50091101_19_dialog_content = "Huh? Why are you looking at me?",
  ui_story_5009_50091101_20_dialog_content = "Uh... I think your strong emotions are interfering with my psychic abilities.",
  ui_story_5009_50091101_21_dialog_content = "Hmph.",
  ui_story_5009_50091101_22_dialog_content = "I'll go stand further away, so my strong emotions don't get in the way.",
  ui_story_5009_50091101_23_dialog_content = "Strong emotions...? It seems Paloma's hatred for Mirren must be quite strong.",
  ui_story_5009_50091101_24_dialog_content = "Even though Paloma speaks little, I believe I have finally figured it out.",
  ui_story_5009_50091101_25_dialog_content = "If Mirren is indeed the mastermind behind all the strife, then it makes perfect sense.",
  ui_story_5009_50091101_26_dialog_content = "Oh?",
  ui_story_5009_50091101_27_dialog_content = "Lady Carleen, the Pyrrhus family was responsible for causing the incident with Beryl.",
  ui_story_5009_50091101_28_dialog_content = "For this reason, the Gautier family believed that they were unjustly exiled as a consequence of the Pyrrhus family's actions.",
  ui_story_5009_50091101_29_dialog_content = "To exact revenge, Mirren orchestrated the Gautier family's rebellion.",
  ui_story_5009_50091101_30_dialog_content = "To Paloma and her kinsfolk, for both families to be massacred as a result of Mirren's plotting is also unjust.",
  ui_story_5009_50091101_31_dialog_content = "As such, the feud between the two families is anything but simple.",
  ui_story_5009_50091101_32_dialog_content = "And Paloma could never forgive Mirren, who was the direct cause of her family's death.",
  ui_story_5009_50091101_33_dialog_content = "Wait a minute... Isn't everything caused by the lapse in fair judgement of Lumopolis authority?",
  ui_story_5009_50091101_34_dialog_content = "...",
  ui_story_5009_50091101_35_dialog_content = "There are still many details that must be clarified. Rest assured, Lady Carleen. I will continue to investigate the matter to the best of my abilities.",
  ui_story_5009_50091101_36_dialog_content = "One thing I still fail to understand, is why both Mirren and Paloma possess such incredible power.",
  ui_story_5009_50091101_37_dialog_content = "I'm standing right here, you know?",
  ui_story_5009_50091101_38_dialog_content = "Is it really that strange for me to be so powerful, considering I've fallen so low as to have even joined the True Order?",
  ui_story_5009_50091101_39_dialog_content = "As for Mirren, from what I have gathered, his power has something to do with that mysterious organization...",
  ui_story_5009_50091101_40_dialog_content = "My thoughts precisely, Miss Paloma.",
  ui_story_5009_50091101_41_dialog_content = "Even the events of seventeen years ago, and everything that has led up until today, could all be attributed to...",
  ui_story_5009_50091101_42_dialog_content = "Don't mince words like that. You two are talking about the Eclipse, right?",
  ui_story_5009_50091101_43_dialog_content = "We've fought with them before. You could say we're old acquaintances now, right? PlayerName?",
  ui_story_5009_50091101_44_dialog_content = "Wait...",
  ui_story_5009_50091101_45_dialog_content = "I can sense something! Mirren still hasn't escaped from Eraveil!",
  ui_story_5009_50091101_46_dialog_content = "There is an underground cave... A lot of high-level Eclipsites are lying dormant in there!",
  ui_story_5009_50091101_47_dialog_content = "What is he planning to do there?",
  ui_story_5009_50091101_48_dialog_content = "Isn't it obvious? Eat the Eclipsites and regain Darkflow.",
  ui_story_5009_50091101_49_dialog_content = "We can't let that happen...",
  ui_story_5009_50091101_50_dialog_content = "PlayerName! Give me a direction!",
  ui_story_5009_50091101_51_dialog_content = "Somewhere over there.",
  ui_story_5009_50091101_52_dialog_content = "You can keep using such powerful psychic abilities in Eclipse... I'm impressed.",
  ui_story_5009_50091101_53_dialog_content = "Mirren Gautier... I'm coming for you.",
  ui_story_5009_50091101_54_dialog_content = "Do you mean to go alone, Paloma?",
  ui_story_5009_50091101_55_dialog_content = "Why not rest for a bit first? We can take him down together once we've all gotten our strength back!",
  ui_story_5009_50091101_56_dialog_content = "Oh? So, I just praised you, and now you think you can command me?",
  ui_story_5009_50091101_57_dialog_content = "Wait, Paloma!",
  ui_story_5009_50091101_58_dialog_content = "She took off, just like that...",
  ui_story_5009_50091101_59_dialog_content = "With her powers, she is more than qualified to operate on her own.",
  ui_story_5009_50091101_60_dialog_content = "Even so, she spent a lot of her strength just now. If Mirren was able to recover his Darkflow...",
  ui_story_5009_50091101_61_dialog_content = "I don't think she'll have a chance of winning.",
  ui_story_5009_50091101_62_dialog_content = "We need to hurry and catch up to her.",
  ui_story_5009_50091101_63_dialog_content = "Another obstacle in the way, huh...",
  ui_story_5009_50091101_64_dialog_content = "Let's do this!",
  ui_story_5009_50091202_1_dialog_content = "You're saying that you knew Paloma, a long time ago?",
  ui_story_5009_50091202_2_dialog_content = "Yes... Back then, she was a quiet, shy, and defenseless little girl.",
  ui_story_5009_50091202_3_dialog_content = "Quiet, shy... and defenseless?",
  ui_story_5009_50091202_4_dialog_content = "Are we still talking about the same Paloma here?",
  ui_story_5009_50091202_5_dialog_content = "We met at the Dawn Academy, many years ago.",
  ui_story_5009_50091202_6_dialog_content = "At the time, I was convinced that she would go on to become the most wonderful nun, but then...",
  ui_story_5009_50091202_7_dialog_content = "I saw her name written on the list of fugitives.",
  ui_story_5009_50091202_8_dialog_content = "For the crimes of rebelling as a family, as well as betraying the church...",
  ui_story_5009_50091202_9_dialog_content = "The Pyrrhus family, in conjunction with the Gautier family, staged a violent rebellion...",
  ui_story_5009_50091202_10_dialog_content = "If she hadn't escaped, would Paloma have been executed by Lumopolis?",
  ui_story_5009_50091202_11_dialog_content = "Like the rest of her family...?",
  ui_story_5009_50091202_12_dialog_content = "...",
  ui_story_5009_50091202_13_dialog_content = "I feel as though... I can understand her now.",
  ui_story_5009_50091202_14_dialog_content = "Being the last survivor of her people, and looking for an explanation for all...",
  ui_story_5009_50091202_15_dialog_content = "I completely understand that feeling.",
  ui_story_5009_50091202_16_dialog_content = "Are you okay, PlayerName?",
  ui_story_5009_50091202_17_dialog_content = "To find the truth and hunt down the culprit, and to exact vengeance in her family's name...",
  ui_story_5009_50091202_18_dialog_content = "You must feel a similar way, PlayerName.",
  ui_story_5009_50091202_19_dialog_content = "There's more than that, a lot more than that.",
  ui_story_5009_50091202_20_dialog_content = "Haven't you guys thought about it? If there's no one to stop these people or change things for the better...",
  ui_story_5009_50091202_21_dialog_content = "These tragedies would be doomed to repeat themselves, over and over again...",
  ui_story_5009_50091202_22_dialog_content = "Indeed. Therefore, we must investigate the matter of their past clearly and find the true cause of this strife. Only then will we prevent it from happening again.",
  ui_story_5009_50091202_23_dialog_content = "But if the problem lies with the nobility of Lumopolis... How will we fix it then?",
  ui_story_5009_50091202_24_dialog_content = "We can answer questions at a different time. Right now, Mirren is our top priority.",
  ui_story_5009_50091202_25_dialog_content = "In here!",
  ui_story_5009_50091202_26_dialog_content = "I'm absolutely certain of it... Mirren is in here!",
  ui_story_5009_50091202_27_dialog_content = "Wait! What's that sound...?",
  ui_story_5009_50091202_28_dialog_content = "<color=#e8d9bb>Rumble...!</color>",
  ui_story_5009_50091202_29_dialog_content = "Watch your footing, everyone!",
  ui_story_5009_50091202_30_dialog_content = "The earthquake stopped...",
  ui_story_5009_50091202_31_dialog_content = "How are these underground structures built so well, that they can withstand a tremor like that?",
  ui_story_5009_50091202_32_dialog_content = "If this is a naturally-formed cave, I'm afraid we've most likely been trapped inside.",
  ui_story_5009_50091202_33_dialog_content = "What was that noise?",
  ui_story_5009_50091202_34_dialog_content = "It's coming from inside the structures!",
  ui_story_5009_50091202_35_dialog_content = "PlayerName... Could it be...?",
  ui_story_5009_50091202_36_dialog_content = "Yeah... I can sense Paloma. It's very likely...",
  ui_story_5009_50091202_37_dialog_content = "That Paloma has already found Mirren.",
  ui_story_5009_50091301_A1_dialog_content = "Mmmmm... Power! Delicious power!",
  ui_story_5009_50091301_1_dialog_content = "<color=#e8d9bb>Rumble...!</color>",
  ui_story_5009_50091301_A2_dialog_content = "Hahaha! Just in time.",
  ui_story_5009_50091301_2_dialog_content = "Mirren Gautier... You're nothing but a cowering, hiding worm.",
  ui_story_5009_50091301_3_dialog_content = "Is it? But you won't even have the chance to be a worm!",
  ui_story_5009_50091301_4_dialog_content = "Ah...!",
  ui_story_5009_50091301_5_dialog_content = "Take it as a compliment. It's impressive that you managed to put up with such a fight all the way here.",
  ui_story_5009_50091301_6_dialog_content = "But the True Order's hidden techniques are nothing more than low-level Luminatics.",
  ui_story_5009_50091301_7_dialog_content = "They are nothing like my power... Extraordinary power bestowed upon me by my master.",
  ui_story_5009_50091301_8_dialog_content = "Ahem... This power you're talking about... Can it only be restored in such a distasteful way?",
  ui_story_5009_50091301_9_dialog_content = "Did turning into a monster also rob you of your sense of taste?",
  ui_story_5009_50091301_10_dialog_content = "I can't imagine how you would be able to eat so many of those foul Eclipsites.",
  ui_story_5009_50091301_11_dialog_content = "Oh? It seems you have yet to realize it, but the most delicious thing in the world... is power!",
  ui_story_5009_50091301_12_dialog_content = "Care to have a taste? Ah yes, I can see it now...",
  ui_story_5009_50091301_13_dialog_content = "If you were to consume Darkflow, you would become far more beautiful than you are now...",
  ui_story_5009_50091301_14_dialog_content = "Do you really think everyone else is like you?",
  ui_story_5009_50091301_15_dialog_content = "Oh, I only wanted to give you a chance, to paint a picture of what you could be...",
  ui_story_5009_50091301_16_dialog_content = "But I suppose it would be easier to just gather your remains and make a specimen out of them!",
  ui_story_5009_50091301_17_dialog_content = "Look, it's Mirren!",
  ui_story_5009_50091301_18_dialog_content = "Oh, no... Paloma, watch out!",
  ui_story_5009_50091301_19_option_content = "Force Boost",
  ui_story_5009_50091301_20_dialog_content = "Dodge backwards!",
  ui_story_5009_50091301_21_dialog_content = "Thank goodness! I didn't think Paloma would avoid that last attack!",
  ui_story_5009_50091301_22_dialog_content = "Still, she looks completely exhausted now...",
  ui_story_5009_50091301_23_dialog_content = "*Coughs* PlayerName...",
  ui_story_5009_50091301_24_dialog_content = "Don't you ever ask for permission before using your psychic abilities?",
  ui_story_5009_50091301_25_option_content = "Not really...",
  ui_story_5009_50091301_26_dialog_content = "I only use my powers like that in case of emergencies!",
  ui_story_5009_50091301_27_option_content = "I had no other choice...",
  ui_story_5009_50091301_28_dialog_content = "I was not allowed to think much in such a dire situation...",
  ui_story_5009_50091301_29_dialog_content = "Oh? Then I should consider myself lucky.",
  ui_story_5009_50091301_30_dialog_content = "What took you so long? You missed quite the performance just now, you know?",
  ui_story_5009_50091301_31_dialog_content = "Though it matters not, I suppose. That's because...",
  ui_story_5009_50091301_32_dialog_content = "The real show is about to begin!",
  ui_story_5009_50091301_33_dialog_content = "Look out, everyone!",
  ui_story_5009_50091301_34_dialog_content = "Not this strange space again...",
  ui_story_5009_50091301_35_dialog_content = "Were we too late? He seems to have regained his strength. I can't imagine how many Eclipsites he ate to recover this much...",
  ui_story_5009_50091301_36_dialog_content = "Out of my way.",
  ui_story_5009_50091301_37_dialog_content = "<color=#e8d9bb>Wham! Wham! Wham!</color>",
  ui_story_5009_50091301_38_dialog_content = "I can't break it! Have I really spent this much power...?",
  ui_story_5009_50091301_39_option_content = "Try to sense",
  ui_story_5009_50091301_40_dialog_content = "Let me try again...",
  ui_story_5009_50091301_41_option_content = "Force Boost!",
  ui_story_5009_50091301_42_dialog_content = "PlayerName...",
  ui_story_5009_50091301_43_dialog_content = "Your psychic ability won't serve you much inside this space.",
  ui_story_5009_50091301_44_dialog_content = "Hang on, let me think... There has to be something we can do.",
  ui_story_5009_50091301_45_dialog_content = "Watch out for the enemy's attacks, everyone!",
  ui_story_5009_50091301_46_dialog_content = "Shh! Quiet...",
  ui_story_5009_50091301_47_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5009_50091301_48_dialog_content = "PlayerName! You find a way out of here; I'll fend off Mirren's attacks!",
  ui_story_5009_50091301_49_dialog_content = "G-Got it!",
  ui_story_5009_50091301_50_dialog_content = "Hahaha! Oh, Paloma... I never thought you would still be so naive after everything has happened.",
  ui_story_5009_50091301_51_dialog_content = "Just try to fend off my attacks!",
  ui_story_5009_50091301_52_dialog_content = "Urgh...",
  ui_story_5009_50091301_53_dialog_content = "We can't keep this up...",
  ui_story_5009_50091301_54_dialog_content = "Mirren! I'm the only representative of Lumopolis here, not them! If you want to take your anger out on somebody, take it out on me! Just let them go!",
  ui_story_5009_50091301_55_dialog_content = "Oh? I seem to have heard something quite interesting.",
  ui_story_5009_50091301_56_dialog_content = "What was that just now? \"Let them go?\" Hahahaha! Don't make me laugh!",
  ui_story_5009_50091301_57_dialog_content = "Are the lives of your comrades the only ones worthy of mercy? Where was that same mercy when my family was being massacred all those years ago?!",
  ui_story_5009_50091301_58_dialog_content = "This must mean that the lives of Miss Paloma's family were also not worthy of your mercy. Am I mistaken?!",
  ui_story_5009_50091301_59_dialog_content = "Mirren Gautier... Your family was innocent, but you are far from it.",
  ui_story_5009_50091301_60_dialog_content = "You chose to become the perpetrator of violence, and in doing so, you doomed your entire family to suffering and death.",
  ui_story_5009_50091301_61_dialog_content = "Your words are nothing more than a waste of time now.",
  ui_story_5009_50091301_62_dialog_content = "Nonsense... It is your words that amount to nothing, not mine!",
  ui_story_5009_50091301_63_dialog_content = "Nothing but a selfish creature... this ends now!",
  ui_story_5009_50091301_64_dialog_content = "Hahaha! Turning a blind eye to reason once again? Our families would never have been exiled if it weren't for that tendency of yours.",
  ui_story_5009_50091301_65_dialog_content = "I had no power before, and I was persecuted because of it.",
  ui_story_5009_50091301_66_dialog_content = "But once I acquired it, people feared and obeyed me... And even looked up to me...",
  ui_story_5009_50091301_67_dialog_content = "Unfortunately, my family failed to understand and accept this, and so they were dealt with by Lumopolis.",
  ui_story_5009_50091301_68_dialog_content = "As for me, I'm quite enjoyed seeing your terrified, self-righteous faces as you stand helpless before my power.",
  ui_story_5009_50091301_69_dialog_content = "This is my justice.",
  ui_story_5009_50091301_70_dialog_content = "Another grandiose monologue about power... I'm so sick of listening to it.",
  ui_story_5009_50091301_71_dialog_content = "You have no right to talk about justice the moment you sell your soul in exchange for power.",
  ui_story_5009_50091301_72_dialog_content = "And don't talk about your family as though they were anything but tools in your eyes.",
  ui_story_5009_50091301_73_dialog_content = "Mirren... are you always so dramatic, or is it another result of your transformation?",
  ui_story_5009_50091301_74_dialog_content = "Hah!",
  ui_story_5009_50091301_78_dialog_content = "Hmph, my patience has run out.",
  ui_story_5009_50091301_79_dialog_content = "It's time to send you all to hell, with the rest of the Caelestites!",
  ui_story_5009_50091301_75_dialog_content = "PlayerName, get out of the way!",
  ui_story_5009_50091301_A3_dialog_content = "Over my dead body!",
  ui_story_5009_50091301_80_dialog_content = "Paloma... Can you still fight?",
  ui_story_5009_50091301_82_dialog_content = "What?!",
  ui_story_5009_50091301_A4_dialog_content = "Don't just stand there like that—try to keep up with me. Let's attack together... Don't stop until this is over!",
  ui_story_5009_50091301_A5_dialog_content = "So, you actually do know what teamwork is! Soldiers, follow me!",
  ui_story_5009_50091301_A6_dialog_content = "I have no other choice... Ice Blossom!",
  ui_story_5009_50091301_A7_dialog_content = "Accept your judgment!",
  ui_story_5009_50091301_A8_dialog_content = "That's right, everyone... We won't take this lying down!",
  ui_story_5009_50091301_76_dialog_content = "Hmph!",
  ui_story_5009_50091301_77_option_content = "Mind link!",
  ui_story_5009_50091301_A9_dialog_content = "Ouch... My head...",
  ui_story_5009_50091301_A10_dialog_content = "But this is an Eraveil... It's not...",
  ui_story_5009_50091301_A11_dialog_content = "Is this for real? My control over Luminatics seems to have improved a little!",
  ui_story_5009_50091301_A12_dialog_content = "Same here.",
  ui_story_5009_50091301_A13_dialog_content = "Everyone's attacks are working... We're breaking free from this place's control!",
  ui_story_5009_50091301_81_dialog_content = "My psychic abilities have also slightly returned!",
  ui_story_5009_50091301_83_dialog_content = "Mirren Gautier... No matter what you've done or what suffering you've caused in the past...",
  ui_story_5009_50091301_84_dialog_content = "You brought destruction to Eraveil in the name of Eclipse!",
  ui_story_5009_50091301_85_dialog_content = "I won't forgive you for this!",
  ui_story_5009_50091301_86_dialog_content = "Hahahaha! Such strong words from such a frail creature!",
  ui_story_5009_50091301_87_dialog_content = "Very well! If this is how it must be... I will use all of my power to crush you!",
  ui_story_5009_50091301_88_dialog_content = "Graaaaaagh!!!",
  ui_story_5009_50091301_89_dialog_content = "Is everyone ready? It's time to end this!",
  ui_story_5009_50091301_90_dialog_content = "Your psychic powers... Have they recovered?",
  ui_story_5009_50091301_91_dialog_content = "Hmph, I'm as ready as I'll ever be. Let's go!",
  ui_story_5009_50091301_92_option_content = "Activate powers!",
  ui_story_5009_50091302_1_dialog_content = "The light is so bright...",
  ui_story_5009_50091302_2_dialog_content = "The Eclipse is starting to fade away.",
  ui_story_5009_50091302_3_dialog_content = "Again! He escaped...",
  ui_story_5009_50091302_4_dialog_content = "Mirren Gautier... is as sly as ever.",
  ui_story_5009_50091302_5_dialog_content = "Once the tables begin to turn, he uses every bit of his ingenuity to get away.",
  ui_story_5009_50091302_6_dialog_content = "We have really wounded him this time. I'm afraid we won't hear anything again for a long time.",
  ui_story_5009_50091302_7_dialog_content = "Mirren Gautier... Did he come to Eraveil seventeen years ago?",
  ui_story_5009_50091302_8_dialog_content = "Why do you ask?",
  ui_story_5009_50091302_9_dialog_content = "Seventeen years ago, when Eraveil and the Caelestites were wiped out... There was an Eclipse in the sky, just like today.",
  ui_story_5009_50091302_10_dialog_content = "I thought that maybe there were...",
  ui_story_5009_50091302_11_dialog_content = "Sorry, but as what I have known...",
  ui_story_5009_50091302_12_dialog_content = "Before our families were exiled and sent to the Lower Lumopolis, I don't think Mirren has ever left Lumopolis.",
  ui_story_5009_50091302_13_dialog_content = "When exactly were your families exiled?",
  ui_story_5009_50091302_14_dialog_content = "Twelve years ago.",
  ui_story_5009_50091302_15_dialog_content = "So... It wasn't him?",
  ui_story_5009_50091302_16_dialog_content = "From what we gathered, I think...",
  ui_story_5009_50091302_17_dialog_content = "Mirren's so-called master is more likely to have been involved.",
  ui_story_5009_50091302_18_dialog_content = "...!",
  ui_story_5009_50091302_19_dialog_content = "Just how much about Eclipse do you truly know, Paloma?",
  ui_story_5009_50091302_20_dialog_content = "I'd like to ask the same thing!",
  ui_story_5009_50091302_21_dialog_content = "The appearance of Eclipse... is likely a power that their organization possesses.",
  ui_story_5009_50091302_22_dialog_content = "In areas affected by the Eclipse, the Luminatics of others are weakened to varying degrees.",
  ui_story_5009_50091302_23_dialog_content = "My psychic ability were also affected from the very beginning...",
  ui_story_5009_50091302_24_dialog_content = "What about that strange space just now? What was it?",
  ui_story_5009_50091302_25_dialog_content = "It was something like a sealed and concentrated Eclipse zone, where its weakening effects are even more pronounced.",
  ui_story_5009_50091302_26_dialog_content = "Breaking out of that space from within is extremely difficult, but destroying it from the outside is far easier.",
  ui_story_5009_50091302_27_dialog_content = "As for the master...",
  ui_story_5009_50091302_28_dialog_content = "My people... were the Caelestites destroyed by the same kind of attack?",
  ui_story_5009_50091302_29_dialog_content = "How do you know so much about Mirren Gautier, Paloma? Or about how the Eclipse works?",
  ui_story_5009_50091302_30_dialog_content = "Oh? Are you suspicious of me now?",
  ui_story_5009_50091302_31_dialog_content = "M-My apologies.",
  ui_story_5009_50091302_32_dialog_content = "I'm simply curious. Why were your powers unaffected by the Eclipse?",
  ui_story_5009_50091302_33_dialog_content = "When you're driven by a thirst for vengeance, you don't notice much outside of that.",
  ui_story_5009_50091302_34_dialog_content = "It's just a price I must pay. I fear you may never understand it.",
  ui_story_5009_50091302_35_dialog_content = "Do you also seek vengeance against Lumopolis?",
  ui_story_5009_50091302_36_dialog_content = "Oh, you seem to be more aware than I gave you credit for, Princess of Lumopolis...",
  ui_story_5009_50091302_37_dialog_content = "Put your mind at ease. It's not time for Lumopolis... yet.",
  ui_story_5009_50091302_38_dialog_content = "Then you should know, that I will not allow any harm to come to Lumopolis or its people.",
  ui_story_5009_50091302_39_dialog_content = "Hmm... We'll just have to wait and see then, won't we?",
  ui_story_5009_50091302_40_dialog_content = "Revenge...",
  ui_story_5009_50091302_41_dialog_content = "I don't know about the others... But I'm sure you understand the feeling all too well, PlayerName.",
  ui_story_5009_50091302_42_dialog_content = "... Would you choose to become an Eclipsite just for your revenge?",
  ui_story_5009_50091302_43_dialog_content = "Your joke is a little too lame for my liking, PlayerName.",
  ui_story_5009_50091302_44_dialog_content = "Let me ask you the same, would you become an Eclipsite just for the sake of vengeance?",
  ui_story_5009_50091302_45_dialog_content = "Of course I wouldn't!",
  ui_story_5009_50091302_46_dialog_content = "Then we're the same!",
  ui_story_5009_50091302_47_dialog_content = "Hahaha... I feel like we have plenty more in common, PlayerName. However...",
  ui_story_5009_50091302_48_dialog_content = "I also feel that chatting like this is a waste of time. I should be going now.",
  ui_story_5009_50091302_49_dialog_content = "Paloma.",
  ui_story_5009_50091302_50_dialog_content = "You and Beryl...",
  ui_story_5009_50091302_51_dialog_content = "Ah... I know what you're trying to ask, PlayerName.",
  ui_story_5009_50091302_52_dialog_content = "My vengeance has nothing to do with Beryl.",
  ui_story_5009_50091302_53_dialog_content = "Then is she... doing okay?",
  ui_story_5009_50091302_54_dialog_content = "Hmph, aren't you guys working together to rebuild the Post?",
  ui_story_5009_50091302_55_dialog_content = "If you really want to know, just write her a letter and ask her yourself.",
  ui_story_5009_50091302_56_dialog_content = "I'm leaving now.",
  ui_story_5009_50091302_57_dialog_content = "Wait, Miss Paloma.",
  ui_story_5009_50091302_58_dialog_content = "What? Thinking about arresting me before I get away?",
  ui_story_5009_50091302_59_dialog_content = "I wish to reopen the investigation on the Pyrrhus and Gautier families and further research the matter.",
  ui_story_5009_50091302_60_dialog_content = "Naturally, if you were to return with me to the Hall of Justice...",
  ui_story_5009_50091302_61_dialog_content = "And what? Give you an opportunity to fulfill your duties by capturing me?",
  ui_story_5009_50091302_62_dialog_content = "Please, Paloma! You know I'm not that kind of person!",
  ui_story_5009_50091302_63_dialog_content = "I want to learn the truth, so that we may set the record straight.",
  ui_story_5009_50091302_64_dialog_content = "Is that so? Then let me ask you something, do you know why the elites of Lumopolis chose to hide the truth?",
  ui_story_5009_50091302_65_dialog_content = "Do you know who was behind it all?",
  ui_story_5009_50091302_66_dialog_content = "No, you don't know.",
  ui_story_5009_50091302_67_dialog_content = "Correct. I don't know, and I don't need to know.",
  ui_story_5009_50091302_68_dialog_content = "I need only know that my role is to investigate the truth.",
  ui_story_5009_50091302_69_dialog_content = "... Huh?",
  ui_story_5009_50091302_70_dialog_content = "Back then, several colleagues and I were dispatched to Umbraton to investigate the matter, but instead we encountered members of Eclipse...",
  ui_story_5009_50091302_71_dialog_content = "*Coughing* Are you alright...?",
  ui_story_5009_50091302_72_dialog_content = "Pittman... My legs are no good anymore...",
  ui_story_5009_50091302_73_dialog_content = "But you... and the others...",
  ui_story_5009_50091302_74_dialog_content = "If you keep wasting time, we're all going to be wiped out!",
  ui_story_5009_50091302_75_dialog_content = "Now go!",
  ui_story_5009_50091302_76_dialog_content = "Their parents and children, husbands and wives...",
  ui_story_5009_50091302_77_dialog_content = "As the only survivor of the attack, I owe them all an explanation for the deaths of their loved ones.",
  ui_story_5009_50091302_78_dialog_content = "I think I understand your feelings a bit better now... But, Your Honor, stop these self-righteous thoughts!",
  ui_story_5009_50091302_79_dialog_content = "With your current position, you will never be able to find the truth.",
  ui_story_5009_50091302_80_dialog_content = "The God of Light has entrusted me with this task. I cannot and shall not fail in my duties.",
  ui_story_5009_50091302_81_dialog_content = "Justice may be a long time in the making, but someday it will be served!",
  ui_story_5009_50091302_82_dialog_content = "...",
  ui_story_5009_50091302_83_dialog_content = "*Sigh* In that case, all I can do...",
  ui_story_5009_50091302_84_dialog_content = "Is wish you luck.",
  ui_story_5009_50091302_85_dialog_content = "Until we meet again, PlayerName!",
  ui_story_5009_50091302_86_dialog_content = "Paloma! Wait!",
  ui_story_5009_50091302_87_dialog_content = "...",
  ui_story_5009_50091302_88_dialog_content = "Is it really alright... To let a fugitive go like that?",
  ui_story_5009_50091302_89_dialog_content = "Let's not get involved.",
  ui_story_5009_50091302_90_dialog_content = "What will you tell your superiors, Pittman?",
  ui_story_5009_50091302_91_dialog_content = "The truth, your highness. I will report to them the indisputable truth.",
  ui_story_5009_50091302_92_dialog_content = "But aren't you concerned that the Hall of Justice will blame you for letting a fugitive escape?",
  ui_story_5009_50091302_93_dialog_content = "It appears as though a number of cases in the last decade were more complex than they seemed and warrant further investigation.",
  ui_story_5009_50091302_94_dialog_content = "I believe the Hall of Justice, as well as the Chief Judge, will not ignore the need for clarification on these cases, much less punish me without good cause.",
  ui_story_5009_50091302_95_dialog_content = "In the name of the God of Light, I swear I will find the truth, no matter the price I must pay.",
  ui_story_5009_50091302_96_dialog_content = "Lumopolis is blessed to have a judge such as yourself. I believe in your cause.",
  ui_story_5009_50091302_97_dialog_content = "I... I believe in you too, Pittman!",
  ui_story_5009_50091302_98_dialog_content = "*Clears throat* Hey, PlayerName!",
  ui_story_5009_50091302_99_dialog_content = "Do you still remember what we came to do, in the first place?",
  ui_story_5009_50091302_100_option_content = "I remember...",
  ui_story_5009_50091302_101_dialog_content = "We came to see Eraveil.",
  ui_story_5009_50091302_102_option_content = "I completely forgot...",
  ui_story_5009_50091302_103_dialog_content = "*Sigh* Didn't we come here to help rebuild the Post?",
  ui_story_5009_50091302_104_dialog_content = "I wonder if Naroxel and the others were affected by the Eclipse?",
  ui_story_5009_50091302_105_dialog_content = "I wouldn't worry too much about that.",
  ui_story_5009_50091302_106_dialog_content = "Communications are back online, and judging from the terminal messages she sent...",
  ui_story_5009_50091302_107_dialog_content = "They seem to be keeping really busy.",
  ui_story_5009_50091302_108_dialog_content = "In that case, we can't afford to rest just yet.",
  ui_story_5009_50091302_109_dialog_content = "Are there any remaining Eclipsites hiding in Eraveil, PlayerName?",
  ui_story_5009_50091302_110_dialog_content = "Yeah... I can sense that there are still a few low-level Eclipsites lurking in the vicinity.",
  ui_story_5009_50091302_111_dialog_content = "Then let us dispatch them quickly, and be done with it.",
  ui_story_5009_50091302_112_dialog_content = "Let's finish them all off before the sun sets, everyone!",
  ui_story_5009_50091302_113_dialog_content = "Let's go!",
  ui_story_5009_50091302_114_dialog_content = "U-Um...",
  ui_story_5009_50091302_115_dialog_content = "You guys are going the wrong way... The Eclipsites are over there!",
  ui_story_5009_50091401_1_dialog_content = "It will be dark soon, it seems.",
  ui_story_5009_50091401_2_dialog_content = "Status report, PlayerName?",
  ui_story_5009_50091401_3_dialog_content = "Eraveil is...",
  ui_story_5009_50091401_4_dialog_content = "Still some left, eh? Seriously... there's no getting rid of them!",
  ui_story_5009_50091401_5_dialog_content = "Where are the rest? They can't hide from me!",
  ui_story_5009_50091401_6_dialog_content = "I don't sense any Eclipsites in Eraveil!",
  ui_story_5009_50091401_7_dialog_content = "Told you! I knew we could clear them out before sundown!",
  ui_story_5009_50091401_8_dialog_content = "Well done, everyone. Anything is possible, so long as we never give up.",
  ui_story_5009_50091401_9_dialog_content = "Are the Eclipsites all gone?",
  ui_story_5009_50091401_10_dialog_content = "Wait... did we win?",
  ui_story_5009_50091401_11_dialog_content = "Yes, we did... and it was all thanks to everyone's help.",
  ui_story_5009_50091401_12_dialog_content = "Yeah! We won!",
  ui_story_5009_50091401_13_dialog_content = "<color=#e8d9bb>Buzz, buzz, buzz...</color>",
  ui_story_5009_50091401_14_dialog_content = "Hmm? Wait... What's that sound?",
  ui_story_5009_50091401_15_dialog_content = "Oh, that's just my terminal's notification sound.",
  ui_story_5009_50091401_16_dialog_content = "S-Sorry, let me just see who it is really quickly...",
  ui_story_5009_50091401_17_dialog_content = "Greetings, Vice.",
  ui_story_5009_50091401_18_dialog_content = "It's Naroxel!",
  ui_story_5009_50091401_19_dialog_content = "Hello, Naroxel! How are you?",
  ui_story_5009_50091401_20_dialog_content = "Oh? It looks like PlayerName is with you, as well.",
  ui_story_5009_50091401_21_dialog_content = "What is your status in Eraveil? Is the area still full of Eclipsite activity?",
  ui_story_5009_50091401_22_dialog_content = "Oh, don't worry! Thanks to everyone's help, we've wiped out the Eclipsites in Eraveil!",
  ui_story_5009_50091401_23_dialog_content = "Thanks to nature's blessings! I was more than worried about your well-being at first...",
  ui_story_5009_50091401_24_dialog_content = "But hearing you sound full of energy has put my mind at ease.",
  ui_story_5009_50091401_25_dialog_content = "It's actually been... quite a long day. How are things going on your side? Any big problems?",
  ui_story_5009_50091401_26_dialog_content = "Everything is proceeding smoothly... But Dove's illness is still a cause for concern.",
  ui_story_5009_50091401_27_dialog_content = "Wait... Dove actually showed up?",
  ui_story_5009_50091401_28_dialog_content = "Yes, but she was very sick, and it was obvious to everyone that she needed rest. I arranged for a transport vehicle to take her back as soon as possible.",
  ui_story_5009_50091401_29_dialog_content = "*Sigh* I wonder if that little pigeon is just faking it to get out of work again...",
  ui_story_5009_50091401_30_dialog_content = "I doubt it, since it seems her illness was caused by overexertion on this job.",
  ui_story_5009_50091401_31_dialog_content = "I didn't know Dove could even regularly-exert herself at her job...",
  ui_story_5009_50091401_32_dialog_content = "She really helped out a lot today. Come and see for yourselves, you'll know what I mean.",
  ui_story_5009_50091401_33_dialog_content = "Huh? O-Okay, then.",
  ui_story_5009_50091401_34_dialog_content = "Oh, and Tweety wants me to tell you that a big surprise is waiting for you at the Post.",
  ui_story_5009_50091401_35_dialog_content = "Although... Doesn't tell them about it defeat the purpose of a surprise?",
  ui_story_5009_50091401_36_dialog_content = "In any case, you must all be exhausted after such a long day.",
  ui_story_5009_50091401_37_dialog_content = "We've prepared hot tea and snacks for you at the Post, to welcome you guys.",
  ui_story_5009_50091401_38_dialog_content = "Roger that! We'll be on our way shortly. See you soon!",
  ui_story_5009_50091401_39_dialog_content = "I wonder what she meant by a big surprise?",
  ui_story_5009_50091401_40_dialog_content = "I'm not sure, but she's always had a knack for doing the unexpected. I'm excited to see what it is!",
  ui_story_5009_50091401_41_dialog_content = "I just hope it's a good surprise, and not a shocking one.",
  ui_story_5009_50091401_42_dialog_content = "Now that Eraveil has been purged of all Eclipsite threats...",
  ui_story_5009_50091401_43_dialog_content = "Your highness, PlayerName, Vice... I believe it is time for me to return to Lumopolis to make my report.",
  ui_story_5009_50091401_44_dialog_content = "What? Leaving so soon?",
  ui_story_5009_50091401_45_dialog_content = "Come now, Pittman. I'm sure the Hall of Justice will be more than understanding if you stayed a while longer.",
  ui_story_5009_50091401_46_dialog_content = "There's no need to be in such a rush.",
  ui_story_5009_50091401_47_dialog_content = "That's right! Not to mention, you still haven't treated your injuries from today...",
  ui_story_5009_50091401_48_dialog_content = "Why not stay with us and rest for a bit? I'd be honored to have you as our guest!",
  ui_story_5009_50091401_49_dialog_content = "Thank you all for your kind hospitality, but I fear I must respectfully decline.",
  ui_story_5009_50091401_50_dialog_content = "Weathering this storm with you all has given me much to think about... as well as strengthened my own resolve.",
  ui_story_5009_50091401_51_dialog_content = "Thanks to all of you, I have gleaned much knowledge and obtained many investigation leads here in Eraveil.",
  ui_story_5009_50091401_52_dialog_content = "I wish to make my report with all haste, and continue with the next step of my investigation.",
  ui_story_5009_50091401_53_dialog_content = "If your heart is really set on it, then we understand...",
  ui_story_5009_50091401_54_dialog_content = "But whenever you have some spare time, remember to come and see us again, okay?",
  ui_story_5009_50091401_55_dialog_content = "Of course, PlayerName. I have a feeling...",
  ui_story_5009_50091401_56_dialog_content = "That we will see each other again very soon.",
  ui_story_5009_50091401_57_dialog_content = "How can these guys just come and go as they please?",
  ui_story_5009_50091401_58_dialog_content = "I feel like we shouldn't be here, but watching the drama unfold is kind of entertaining, huh?",
  ui_story_5009_50091401_59_dialog_content = "Ahem! Is there something you wish to share with us, soldiers?",
  ui_story_5009_50091401_60_dialog_content = "N-No, ma'am!",
  ui_story_5009_50091401_61_dialog_content = "W-We were just discussing how best to make our way back!",
  ui_story_5009_50091401_62_dialog_content = "If no one minds, I can carry everyone back on the Colossus?",
  ui_story_5009_50091401_63_dialog_content = "I only have one condition, though.",
  ui_story_5009_50091401_64_dialog_content = "A condition? They were here to help! Don't you think it's too over to ask for condition?",
  ui_story_5009_50091401_65_dialog_content = "Just hear what I have to say first, Vice!",
  ui_story_5009_50091401_66_dialog_content = "What's your condition? We're listening.",
  ui_story_5009_50091401_67_dialog_content = "You're all my very first guests I bring back to Eraveil, my homeland...",
  ui_story_5009_50091401_68_dialog_content = "But after all that we've been through today, and all the help you've given us, I feel like I've been a terrible host...",
  ui_story_5009_50091401_69_dialog_content = "So I'd like to ask everyone... Could you please give me another chance to treat you all as my guests, and be a proper host?",
  ui_story_5009_50091401_70_dialog_content = "Is that all? Hahaha! I've got no objection here! What about you guys?",
  ui_story_5009_50091401_71_dialog_content = "Sounds good to me! Finally, some rest! Alright!",
  ui_story_5009_50091401_72_dialog_content = "I'm sorry, PlayerName... I guess I jumped to the wrong conclusion.",
  ui_story_5009_50091401_73_dialog_content = "But how exactly do you plan on treating everyone?",
  ui_story_5009_50091401_74_dialog_content = "Well, actually... A few days ago, I decided to prepare for Windland Day...",
  ui_story_5009_50091401_75_dialog_content = "I ordered lots of snacks and drinks through the Courier Union. They should arrive sometime tomorrow.",
  ui_story_5009_50091401_76_dialog_content = "PlayerName... Did it come across to you to look at the expense sheet on the Colossus before you order anything?!",
  ui_story_5009_50091401_77_dialog_content = "A-Anyways... We should really get back to the Post first, don't you think? Naroxel is still waiting for us, you know!",
  ui_story_5009_50091401_78_dialog_content = "They even made tea and snacks for us!",
  ui_story_5009_50091401_79_dialog_content = "Yeah! Let's go!",
  ui_story_5009_50091401_80_dialog_content = "<color=#e8d9bb>Growl...</color>",
  ui_story_5009_50091401_81_dialog_content = "Wait! I think I heard the sound of an Eclipsite just now!",
  ui_story_5009_50091401_82_dialog_content = "Do you sense anything, PlayerName?",
  ui_story_5009_50091401_83_dialog_content = "Uh... Sorry, I think that was my stomach grumbling...",
  ui_story_5009_50091401_84_dialog_content = "A false alarm...",
  ui_story_5009_50091401_85_dialog_content = "Since there's nothing to worry about, we should pick up the pace a little more.",
  ui_story_5009_50091401_86_dialog_content = "We're almost to the Post, so let's not keep them waiting!",
  ui_story_5009_50091401_87_dialog_content = "Okay... Although I wouldn't say my empty stomach is nothing to worry about...",
  ui_story_5009_50091401_88_dialog_content = "Can you keep walking, PlayerName? Or should I have Bessie carry you back?",
  ui_story_5009_50091401_89_dialog_content = "N-Naroxel?! Have you been here this whole time?",
  ui_story_5009_50091401_90_dialog_content = "I'm sorry, did I startle you?",
  ui_story_5009_50091401_91_dialog_content = "Tweety was starting to get worried because you were taking so long, so she asked me to come find you.",
  ui_story_5009_50091401_92_dialog_content = "I just happened to hear your comment right as I found you all...",
  ui_story_5009_50091401_93_dialog_content = "I-It's no big deal, really...",
  ui_story_5009_50091401_94_dialog_content = "That's so considerate of you, Naroxel, Tweety!",
  ui_story_5009_50091401_95_dialog_content = "Except... I don't see Tweety anywhere?",
  ui_story_5009_50091401_96_dialog_content = "Maybe she's afraid of the dark?",
  ui_story_5009_50091401_97_dialog_content = "No, it's just that... somebody had to stay and watch over the Post, that's all.",
  ui_story_5009_50091401_98_dialog_content = "Sounds to me like she's busy preparing her legendary big surprise.",
  ui_story_5009_50091401_99_dialog_content = "Anyways... This way everyone!",
  ui_story_5009_50091401_100_dialog_content = "<color=#e8d9bb>Creeaak...</color>",
  ui_story_5009_50091401_101_dialog_content = "Wow...!",
  ui_story_5009_50091401_102_dialog_content = "Those shelves and that counter... They all look so familiar.",
  ui_story_5009_50091401_103_dialog_content = "If I'm not mistaken, the Post in Lumopolis is designed similarly.",
  ui_story_5009_50091401_104_dialog_content = "But even so, this mailbox is completely different. Somehow it reminds me of Soroz...",
  ui_story_5009_50091401_105_dialog_content = "That's correct. This is the Eraveil Post's self-serve mailbox, designed by the Caelestites themselves.",
  ui_story_5009_50091401_106_dialog_content = "Thankfully, it's still operational after all this time.",
  ui_story_5009_50091401_107_dialog_content = "Hey, look what I found on this shelf over here!",
  ui_story_5009_50091401_108_dialog_content = "Postcards... from ten years ago! I've only seen something like this in the museum!",
  ui_story_5009_50091401_109_dialog_content = "And there's even an aquarium in here!",
  ui_story_5009_50091401_110_dialog_content = "Leave it to Naroxel to bring the spirit of nature into a place like this!",
  ui_story_5009_50091401_111_dialog_content = "On that subject, Dove spent a lot of time and energy to procure the fish you see inside the aquarium.",
  ui_story_5009_50091401_112_dialog_content = "Dove? I never would have guessed...",
  ui_story_5009_50091401_113_dialog_content = "I'm so jealous of you, PlayerName! None of the Posts in the Illumina Federation are as cozy as this one!",
  ui_story_5009_50091401_114_dialog_content = "Hmm? Why aren't you saying anything, PlayerName?",
  ui_story_5009_50091401_115_dialog_content = "I... I just feel really excited. So excited... that I don't really know how to express my feelings right now.",
  ui_story_5009_50091401_116_dialog_content = "This is... the first room in Eraveil to have lights.",
  ui_story_5009_50091401_117_dialog_content = "And it's been decorated so beautifully... Is this really just a Post?",
  ui_story_5009_50091401_118_dialog_content = "I would love to live here, if it was allowed...",
  ui_story_5009_50091401_119_dialog_content = "Meeoow!",
  ui_story_5009_50091401_120_dialog_content = "Haha! Sorry, it looks like you won't be the first resident here!",
  ui_story_5009_50091401_121_dialog_content = "You know, PlayerName, if you really wanted to live here... You would be welcome to do so, as an employee of the Courier's Union!",
  ui_story_5009_50091401_122_dialog_content = "But before any of that... Do you still remember this acceptance letter?",
  ui_story_5009_50091401_123_dialog_content = "I do, it's just...",
  ui_story_5009_50091401_124_dialog_content = "I don't think I could make heads or tails of it, I'm too tired for reading now.",
  ui_story_5009_50091401_125_dialog_content = "Maybe you could give PlayerName the main points of the letter, Naroxel? Would that be okay?",
  ui_story_5009_50091401_126_dialog_content = "Not a problem. If the Courier Union's reconstruction of this Post has adequately met your work expectations...",
  ui_story_5009_50091401_127_dialog_content = "Actually, it exceeded my expectations... By about a hundred-times over!",
  ui_story_5009_50091401_128_dialog_content = "Thank you for your input. Then, if you would, please sign your name below, and remember...",
  ui_story_5009_50091401_129_dialog_content = "Once your signature is complete, your contract with our Posts is officially in effect.",
  ui_story_5009_50091401_130_dialog_content = "What exactly do you mean by officially in effect?",
  ui_story_5009_50091401_131_dialog_content = "Within the Courier Union's transportation network, the landmark for the Eraveil Post will be lit once again.",
  ui_story_5009_50091401_132_dialog_content = "In other words, Eraveil will then be able to receive mails from all over the world.",
  ui_story_5009_50091401_133_dialog_content = "(Back before the disaster... people of Eraveil came here to receive letters from Illumina, and Lumopolis...)",
  ui_story_5009_50091401_134_dialog_content = "(And even Northland?)",
  ui_story_5009_50091401_135_dialog_content = "(Does that mean... That the Caelestites also used this place...)",
  ui_story_5009_50091401_136_dialog_content = "(To send messages to the world, as well? Letters with their joy and sadness?)",
  ui_story_5009_50091401_137_dialog_content = "(If I sign my name, this Post will go back to the way it was... seventeen years ago.)",
  ui_story_5009_50091401_138_dialog_content = "(If I sign my name, Eraveil will come back to life once again on every map in the world...)",
  ui_story_5009_50091401_139_dialog_content = "Do you still have any questions or concerns, PlayerName?",
  ui_story_5009_50091401_140_dialog_content = "No, I just need to know where to sign my name. I'm going...",
  ui_story_5009_50091401_141_dialog_content = "To bring Eraveil back to life!",
  ui_story_5009_50091401_142_dialog_content = "Right here, if you would. I don't believe I have ever seen someone so excited about signing a contract before!",
  ui_story_5009_50091401_143_dialog_content = "Signature:",
  ui_story_5009_50091401_A1_dialog_content = "...",
  ui_story_5009_50091401_144_option_content = "PlayerName",
  ui_story_5009_50091401_145_dialog_content = "<color=#e8d9bb>Gong... Gong... Gong...</color>",
  ui_story_5009_50091401_146_dialog_content = "Is it midnight already?",
  ui_story_5009_50091401_147_dialog_content = "I didn't realize it had gotten so late...",
  ui_story_5009_50091401_148_dialog_content = "It's already tomorrow... That means, it's time for...",
  ui_story_5009_50091401_149_dialog_content = "Urgh...",
  ui_story_5009_50091401_150_dialog_content = "Huh? Carleen, look out!",
  ui_story_5009_50091401_151_dialog_content = "Ice Blossom! Spread out!",
  ui_story_5009_50091401_152_dialog_content = "Is this... Soroz?",
  ui_story_5009_50091401_153_dialog_content = "But the material... It's a doll of Soroz!",
  ui_story_5009_50091401_154_dialog_content = "It's... So... Cute! Where did this even come from?",
  ui_story_5009_50091401_155_dialog_content = "This ought to be the surprise Tweety was talking about. It ended up being a shocking surprise, after all...",
  ui_story_5009_50091401_156_dialog_content = "Finawwy you guys notice me!",
  ui_story_5009_50091401_157_dialog_content = "Eh? Was that Tweety just now? I heard her voice, but I don't see her anywhere...",
  ui_story_5009_50091401_158_dialog_content = "I'm up here... I got caught in Carween's ice!",
  ui_story_5009_50091401_159_dialog_content = "I had no choice. I was afraid Tweety was going to fall down, as well... Let me undo the freezing.",
  ui_story_5009_50091401_160_dialog_content = "Thank you, Carween! But... did you forget that I have wings?",
  ui_story_5009_50091401_161_dialog_content = "But being fwozen wike that... it feels nice!",
  ui_story_5009_50091401_162_dialog_content = "Then would you like for me to freeze you again?",
  ui_story_5009_50091401_163_dialog_content = "N-No, thanks! Once is enough...",
  ui_story_5009_50091401_164_dialog_content = "Were you waiting on the crossbeam this whole time, Tweety?",
  ui_story_5009_50091401_165_dialog_content = "Yep! I was waiting for evewybody all awong!",
  ui_story_5009_50091401_166_dialog_content = "That way, I could swoop in with my big surpwise!",
  ui_story_5009_50091401_167_dialog_content = "But... I fell asweep by accident... And the bell woke me up just now...",
  ui_story_5009_50091401_168_dialog_content = "Sowwy, PlayerName... My big surpwise was a big let-down...",
  ui_story_5009_50091401_169_dialog_content = "You don't have anything to apologize for, Tweety! You made this place look amazing... I didn't even have time to properly thank you for it.",
  ui_story_5009_50091401_170_dialog_content = "Also, the midnight bell just tolled, which means today is officially the Windland Festival.",
  ui_story_5009_50091401_171_dialog_content = "The books say that on this holiday, the Caelestites would also hang up dolls like this.",
  ui_story_5009_50091401_172_dialog_content = "This surprise of yours is absolutely perfect for the occasion!",
  ui_story_5009_50091401_173_dialog_content = "R-Reawwy? I'm so happy to hear that!",
  ui_story_5009_50091401_174_dialog_content = "So you reawwy wike my surpwise, PlayerName?",
  ui_story_5009_50091401_175_dialog_content = "Of course I do! But where did you find something like this?",
  ui_story_5009_50091401_176_dialog_content = "This was, uh... our best attempt at re-creating a mini size of Soroz.",
  ui_story_5009_50091401_177_dialog_content = "It isn't perfect, by any means... But we did fill it with real snacks!",
  ui_story_5009_50091401_178_dialog_content = "It's awso our way of giving you our best wishes, PlayerName!",
  ui_story_5009_50091401_179_dialog_content = "It looks just like Soroz! Besides, it's way better than anything I've ever made...",
  ui_story_5009_50091401_180_dialog_content = "Oh? Does this mean that spider puppet on the Colossus, the one with the frog eyes and the bat wings...",
  ui_story_5009_50091401_181_dialog_content = "That was your work, PlayerName?",
  ui_story_5009_50091401_182_dialog_content = "S-Stop it, Vice! The others aren't supposed to know that...",
  ui_story_5009_50091401_183_dialog_content = "So PlayerName? Wanna smash it open and twy the snacks inside?",
  ui_story_5009_50091401_184_dialog_content = "I picks them all especiawwy for you!",
  ui_story_5009_50091401_185_dialog_content = "But you and Naroxel worked so hard on it, Tweety. Not to mention, it looks just like Soroz...",
  ui_story_5009_50091401_186_dialog_content = "I don't think I can break it.",
  ui_story_5009_50091401_187_dialog_content = "B-But if you don't bweak it, it won't be a real celebwation, PlayerName...",
  ui_story_5009_50091401_188_dialog_content = "Have you forgotten, Tweety?",
  ui_story_5009_50091401_189_dialog_content = "Ah! That's wight! Dove made those fancy fwying lights, too!",
  ui_story_5009_50091401_190_dialog_content = "Flying... Lights?",
  ui_story_5009_50091401_191_dialog_content = "Does she mean the Dandelion Lanterns that the Caelestites would set off during their holidays?",
  ui_story_5009_50091401_192_dialog_content = "Wait... Dove can make Dandelion Lanterns?!",
  ui_story_5009_50091401_193_dialog_content = "I asked before, but are we still talking about the same Dove?!",
  ui_story_5009_50091401_194_dialog_content = "Dove did say that she had learned much in Illumina...",
  ui_story_5009_50091401_195_dialog_content = "And she happened upon an instruction guide on how to craft Dandelion Lanterns, so she grabbed it without a second thought.",
  ui_story_5009_50091401_196_dialog_content = "I can't wait to pway with those pwetty lights!",
  ui_story_5009_50091401_197_dialog_content = "Wet's go out on the pwatform!",
  ui_story_5009_50091401_198_dialog_content = "W-Watch your steps, Tweety! Don't run so fast!",
  ui_story_5009_50091401_199_dialog_content = "It's okay! I have wings, wemember?",
  ui_story_5009_50091401_200_dialog_content = "<color=#e8d9bb>Crash...!</color>",
  ui_story_5009_50091401_201_dialog_content = "Owie...",
  ui_story_5009_50091401_202_dialog_content = "Are you okay, Tweety? You took a big fall just now! Does it hurt?",
  ui_story_5009_50091401_203_dialog_content = "Thanks, Wice... It doesn't hurt anymore.",
  ui_story_5009_50091401_204_dialog_content = "I just bumped into a lit wantern, that's all... I gots a wittle burned, but I'm fine now!",
  ui_story_5009_50091401_205_dialog_content = "They really do look like dandelions once you light them up...",
  ui_story_5009_50091401_206_dialog_content = "PlayerName, count to three, and we'll let go of our Dandelion Lanterns at the same time, okay?",
  ui_story_5009_50091401_207_dialog_content = "Sure! One... Two... Three! Lift off!",
  ui_story_5009_50091401_208_dialog_content = "Go, go, go!",
  ui_story_5009_50091401_209_dialog_content = "Glowing lanterns against a backdrop of countless stars and the brilliant aurora... A rare sight that fills the eyes and heart with wonder.",
  ui_story_5009_50091401_210_dialog_content = "It's been a while since I've heard you say something so poetic, Carleen!",
  ui_story_5009_50091401_211_dialog_content = "A beautiful holiday like this wouldn't be complete without a poem or two.",
  ui_story_5009_50091401_212_dialog_content = "You should have taken more literature lessons during your studies in Lumopolis, Vice.",
  ui_story_5009_50091401_213_dialog_content = "If that's the case, a poetry contest might be in order.",
  ui_story_5009_50091401_214_dialog_content = "I never really understood literature or poetry, but just now...",
  ui_story_5009_50091401_215_dialog_content = "For a moment, I really felt as though the people who have long since left us were back at my side.",
  ui_story_5009_50091401_216_dialog_content = "And then, they laughed as they turned around, taking my thoughts and wishes with them...",
  ui_story_5009_50091401_217_dialog_content = "I think we should all make a wish!",
  ui_story_5009_50091401_218_dialog_content = "But I don't recall the Windland Festival having that sort of tradition? What do you think, PlayerName?",
  ui_story_5009_50091401_219_dialog_content = "Look over there, everyone! Are my eyes playing tricks on me, or is something flying towards us?",
  ui_story_5009_50091401_220_dialog_content = "As expected, it appears this Post is going to be busy on its very first day of operations.",
  ui_story_5009_50091401_221_dialog_content = "Then those things in the sky...",
  ui_story_5009_50091401_222_dialog_content = "I believe those are couriers carrying letters from around the world, PlayerName.",
  ui_story_5009_50091401_223_dialog_content = "I never realized the Courier Union worked this swiftly...",
  ui_story_5009_50091401_224_dialog_content = "PlayerName just signed his name a few minutes ago, and they're already showing up!",
  ui_story_5009_50091401_225_dialog_content = "Then the letters they're carrying...",
  ui_story_5009_50091401_226_dialog_content = "Precisely. They are letters that were meant for the people of Eraveil for the last seventeen years.",
  ui_story_5009_50091401_227_dialog_content = "And today, on the day of the Windland Festival...",
  ui_story_5009_50091401_228_dialog_content = "Their hopes, their concerns, their voices... They will finally reach their destination.",
  ui_story_5009_50091401_229_dialog_content = "Even so, I never would have thought...",
  ui_story_5009_50091401_230_dialog_content = "That so many couriers would be available to deliver seventeen years' worth of letters in one run. It really is quite a sight to behold.",
  ui_story_5009_50091401_231_dialog_content = "You're going to be busy these next few days, Tweety.",
  ui_story_5009_50091401_232_dialog_content = "Yep! I'm fine with it, I wike my job!",
  ui_story_5009_50091401_233_dialog_content = "If only Tweety could come to work in Illumina...",
  ui_story_5009_50091401_234_dialog_content = "That would be gweat! Then I could see Dove evewyday!",
  ui_story_5009_50091401_235_dialog_content = "But I don't know if I could ever weave the nest or my fellow Northland buddies behind...",
  ui_story_5009_50091401_236_dialog_content = "I just saw one of my good fwiends! She is coming to dewiver the wetters!",
  ui_story_5009_50091401_237_dialog_content = "Not so quickly, Tweety...!",
  ui_story_5009_50091401_238_dialog_content = "<color=#e8d9bb>Crash...!</color>",
  ui_story_5009_50091401_239_dialog_content = "Owie... What's on my face? Itchy...",
  ui_story_5009_50091401_240_dialog_content = "You crushed one of the Dandelion Lanterns, Tweety... Your face is covered in white fluff!",
  ui_story_5009_50091401_241_dialog_content = "Hahaha! It's so cute! It actually suits her!",
  ui_story_5009_50091401_242_dialog_content = "Heh...",
  ui_story_5009_50091401_243_dialog_content = "Wow, I did it! I finawwy made Carween smile! Hahaha!",
  ui_story_5009_50091401_244_dialog_content = "Hahahahaha!",
  ui_story_5009_50091401_245_dialog_content = "And so, that's how I spent my first Windland Festival.",
  ui_story_5009_50091401_246_dialog_content = "Before the festival...",
  ui_story_5009_50091401_247_dialog_content = "There was pain...",
  ui_story_5009_50091401_248_dialog_content = "There was anger...",
  ui_story_5009_50091401_249_dialog_content = "There was change...",
  ui_story_5009_50091401_250_dialog_content = "And there were goodbyes...",
  ui_story_5009_50091401_251_dialog_content = "Turns out, there are plenty of people just like me out in the world.",
  ui_story_5009_50091401_252_dialog_content = "But because of the choices we made, we walked down different paths in life.",
  ui_story_5009_50091401_253_dialog_content = "At the points where our destinies diverge, all we can do is wave farewell to one another...",
  ui_story_5009_50091401_254_dialog_content = "But I think that, as long as we make our choices with a clear conscience, maybe someday we can become friends.",
  ui_story_5009_50091401_255_dialog_content = "And that someday, those selfish, wicked traitors will get what they deserve, as well.",
  ui_story_5009_50091401_256_dialog_content = "After all that I've been through, I can't help but feel more and more grateful for the friends that I've made along the way.",
  ui_story_5009_50091401_257_dialog_content = "Especially... on a holiday like this.",
  ui_story_5009_50091401_258_dialog_content = "I used to believe that holidays were like any other days. I didn't understand the point of celebrating anything.",
  ui_story_5009_50091401_259_dialog_content = "But now, I finally understand.",
  ui_story_5009_50091401_260_dialog_content = "On a special day, to be able to reminisce with your friends, and share your hopes for the future...",
  ui_story_5009_50091401_261_dialog_content = "It's such a warm and fortunate thing to experience.",
  ui_story_5009_50091401_262_dialog_content = "These last few days, the Post has received letters from all over, at all hours of the day.",
  ui_story_5009_50091401_263_dialog_content = "Even though most of them aren't meant for me...",
  ui_story_5009_50091401_264_dialog_content = "But Naroxel says that, as the last of the Caelestites, I can act as their sole recipient and open them, if I want.",
  ui_story_5009_50091401_265_dialog_content = "\"Responding to everyone's wishes is a very romantic notion.\"",
  ui_story_5009_50091401_266_dialog_content = "Would my dearly-departed people want me to continue carrying their thoughts and feelings?",
  ui_story_5009_50091401_267_dialog_content = "Everyone says that of course they would...",
  ui_story_5009_50091401_268_dialog_content = "But before any of that, I've decided... That I have to send out my first letter from Eraveil.",
  ui_story_5009_50091401_269_dialog_content = "I write in my diary all the time, but writing a letter feels different.",
  ui_story_5009_50091401_270_dialog_content = "I keep worrying that my wording won't measure up to the occasion. I keep rewriting and erasing my thoughts...",
  ui_story_5009_50091401_271_dialog_content = "After all, I'm representing all of Caelestite-kind in thanking everyone for all that they've done for us.",
  ui_story_5009_50091401_272_dialog_content = "Hmm... I wonder if they've gotten my letter...",
  ui_story_5009_50091401_273_dialog_content = "The Lin family in Umbraton..."
}
return config
